{
  "name": "Church Management System",
  "description": "A comprehensive, offline-first desktop application for managing church members, attendance, finances, and events with role-based access control."
}

import { app, BrowserWindow, ipcMain, dialog } from 'electron';
import * as path from 'path';
import { PrismaClient } from '@prisma/client';
import * as bcrypt from 'bcryptjs';
import * as fs from 'fs';

const prisma = new PrismaClient();

function createWindow() {
  const win = new BrowserWindow({
    width: 1200,
    height: 800,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
    },
    title: "Church Management System",
  });

  if (process.env.NODE_ENV === 'development') {
    win.loadURL('http://localhost:5173');
  } else {
    win.loadFile(path.join(__dirname, '../dist/index.html'));
  }
}

app.whenReady().then(() => {
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', async () => {
  await prisma.$disconnect();
  if (process.platform !== 'darwin') app.quit();
});

// IPC Handlers for Database Operations
ipcMain.handle('auth:login', async (_, { email, password }) => {
  try {
    const user = await prisma.user.findUnique({ where: { email } });
    if (!user) return { error: 'User not found' };
    const valid = await bcrypt.compare(password, user.password);
    if (!valid) return { error: 'Invalid password' };
    return { user: { id: user.id, email: user.email, role: user.role, fullName: user.fullName } };
  } catch (err: any) {
    return { error: err.message };
  }
});

ipcMain.handle('db:getStats', async () => {
  const memberCount = await prisma.member.count();
  const visitorCount = await prisma.visitor.count();
  const income = await prisma.finance.aggregate({
    _sum: { amount: true },
    where: { type: { in: ['TITHE', 'OFFERING', 'DONATION'] } }
  });
  const expenses = await prisma.finance.aggregate({
    _sum: { amount: true },
    where: { type: 'EXPENSE' }
  });

  return { 
    members: memberCount, 
    visitors: visitorCount, 
    totalIncome: income._sum.amount || 0,
    totalExpenses: expenses._sum.amount || 0
  };
});

ipcMain.handle('db:getMembers', async (_, query = '') => {
  return await prisma.member.findMany({
    where: {
      OR: [
        { fullName: { contains: query } },
        { email: { contains: query } },
        { phone: { contains: query } }
      ]
    },
    orderBy: { createdAt: 'desc' }
  });
});

ipcMain.handle('db:addMember', async (_, memberData) => {
  return await prisma.member.create({ data: memberData });
});

ipcMain.handle('db:getFinances', async () => {
  return await prisma.finance.findMany({
    include: { member: true },
    orderBy: { date: 'desc' }
  });
});

ipcMain.handle('db:addFinance', async (_, financeData) => {
  return await prisma.finance.create({ data: financeData });
});

ipcMain.handle('db:backup', async () => {
  const { filePath } = await dialog.showSaveDialog({
    title: 'Save Database Backup',
    defaultPath: 'church_backup.db',
    filters: [{ name: 'SQLite DB', extensions: ['db'] }]
  });

  if (filePath) {
    fs.copyFileSync(path.join(__dirname, '../prisma/dev.db'), filePath);
    return { success: true };
  }
  return { success: false };
});

import { contextBridge, ipcRenderer } from 'electron';

contextBridge.exposeInMainWorld('api', {
  login: (credentials: any) => ipcRenderer.invoke('auth:login', credentials),
  getStats: () => ipcRenderer.invoke('db:getStats'),
  getMembers: (query: string) => ipcRenderer.invoke('db:getMembers', query),
  addMember: (data: any) => ipcRenderer.invoke('db:addMember', data),
  getFinances: () => ipcRenderer.invoke('db:getFinances'),
  addFinance: (data: any) => ipcRenderer.invoke('db:addFinance', data),
  backupDatabase: () => ipcRenderer.invoke('db:backup'),
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import App from './App';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Members from './pages/Members';
import Finances from './pages/Finances';

const Root = () => {
  const [user, setUser] = React.useState<any>(null);

  // Simple auth check simulation for demo
  const isAuthenticated = !!user;

  return (
    <Router>
      <Routes>
        <Route path="/login" element={<Login onLogin={setUser} />} />
        <Route 
          path="/*" 
          element={isAuthenticated ? <App user={user} /> : <Navigate to="/login" replace />} 
        />
      </Routes>
    </Router>
  );
};

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error("Root element not found");
const root = ReactDOM.createRoot(rootElement);
root.render(<Root />);

import React from 'react';
