    const income = await prisma.finance.aggregate({
      _sum: { amount: true },
      where: { type: { in: ['TITHE', 'OFFERING', 'DONATION', 'PLEDGE'] } }
    });
    const expenses = await prisma.finance.aggregate({
      _sum: { amount: true },
      where: { type: 'EXPENSE' }
    });

    return { 
      members: memberCount, 
      visitors: visitorCount, 
      totalIncome: income._sum.amount || 0,
      totalExpenses: expenses._sum.amount || 0
    };
  } catch (err) {
    return { members: 0, visitors: 0, totalIncome: 0, totalExpenses: 0 };
  }
});

