interface LoginProps {
  onLogin: (user: any) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [role, setRole] = useState('ADMIN');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      let res;
      // Use window.api (which now has a fallback in index.tsx)
      const api = (window as any).api;

      if (isRegister) {
        res = await api.register({ email, password, fullName, role });
      } else {
        res = await api.login({ email, password });
      }

      if (res.user) {
        onLogin(res.user);
      } else {
        setError(res.error || 'Authentication failed. Please check your details.');
      }
    } catch (err: any) {
      console.error("Auth Exception:", err);
      setError(`System Exception: ${err.message || 'The database is currently unavailable.'}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative overflow-hidden">
      {/* Visual background flares */}
      <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-indigo-600/10 rounded-full blur-[150px]"></div>
