import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import App from './App';
import Login from './pages/Login';

// --- MOCK API FALLBACK (Local Storage) ---
if (typeof (window as any).api === 'undefined') {
  console.warn("Electron API not found. Falling back to Local Storage mode.");

  (window as any).api = {
    register: async (data: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      if (users.find((u: any) => u.email === data.email)) return { error: 'Email already exists' };
      const newUser = { ...data, id: Math.random().toString(36).substr(2, 9) };
      users.push(newUser);
      localStorage.setItem('cms_users', JSON.stringify(users));
      return { user: newUser };
    },
    login: async (credentials: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      const user = users.find((u: any) => u.email === credentials.email && u.password === credentials.password);
      if (!user) return { error: 'Invalid credentials or user not found' };
      return { user };
    },
    getStats: async () => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const income = finances.filter((f: any) => f.type !== 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      const expenses = finances.filter((f: any) => f.type === 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      return { members: members.length, visitors: 0, totalIncome: income, totalExpenses: expenses };
    },
    getMembers: async (query: string) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      return members.filter((m: any) => m.fullName.toLowerCase().includes(query.toLowerCase()));
    },
    addMember: async (data: any) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const newMember = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      members.push(newMember);
      localStorage.setItem('cms_members', JSON.stringify(members));
      return newMember;
    },
    getFinances: async () => JSON.parse(localStorage.getItem('cms_finances') || '[]'),
    addFinance: async (data: any) => {
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const newFinance = { ...data, id: Math.random().toString(36).substr(2, 9), date: new Date() };
      finances.push(newFinance);
      localStorage.setItem('cms_finances', JSON.stringify(finances));
      return newFinance;
    },
    getEvents: async () => JSON.parse(localStorage.getItem('cms_events') || '[]'),
    addEvent: async (data: any) => {
      const events = JSON.parse(localStorage.getItem('cms_events') || '[]');
      const newEvent = { ...data, id: Math.random().toString(36).substr(2, 9) };
      events.push(newEvent);
      localStorage.setItem('cms_events', JSON.stringify(events));
      return newEvent;
    },
    getSettings: async () => JSON.parse(localStorage.getItem('cms_settings') || '{"churchName": "My Local Church", "branch": "Main Headquarters"}'),
    updateSettings: async (data: any) => {
      localStorage.setItem('cms_settings', JSON.stringify(data));
      return data;
    },
    backupDatabase: async () => {
      alert("Simulated: Database backup exported to ChurchManager_Backup.db");
      return { success: true };
    }
  };
}

const Root = () => {
  const [user, setUser] = React.useState<any>(() => {
    const saved = localStorage.getItem('cms_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const handleLogin = (userData: any) => {
    setUser(userData);
    localStorage.setItem('cms_current_user', JSON.stringify(userData));
