        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-2 bg-slate-900 hover:bg-black text-white font-bold py-3 px-6 rounded-2xl shadow-xl transition-all"
        >
          <Plus size={18} />
          <span>New Event</span>
        </button>
      </div>

      {loading ? (
        <div className="py-20 flex flex-col items-center justify-center text-slate-300">
          <Loader2 size={48} className="animate-spin mb-4" />
          <p className="font-bold">Syncing calendar...</p>
        </div>
      ) : events.length === 0 ? (
        <div className="bg-white p-20 rounded-3xl border border-slate-100 flex flex-col items-center justify-center text-center">
          <Calendar size={64} className="text-slate-100 mb-6" strokeWidth={1} />
          <h3 className="text-xl font-black text-slate-800 mb-2">No Scheduled Events</h3>
          <p className="text-slate-400 max-w-xs font-medium">Plan your next worship service or community outreach program today.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {events.map((event) => (
            <div key={event.id} className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm hover:shadow-md transition-shadow group">
              <div className="flex justify-between items-start mb-4">
                <div className="w-12 h-12 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center">
                  <Calendar size={24} />
                </div>
                <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${
                  event.status === 'UPCOMING' ? 'bg-amber-50 text-amber-600' : 'bg-slate-100 text-slate-500'
                }`}>
                  {event.status}
                </span>
              </div>
              <h3 className="text-lg font-black text-slate-800 mb-2">{event.title}</h3>
              <p className="text-sm text-slate-500 line-clamp-2 mb-6 font-medium">{event.description || 'No description provided.'}</p>

              <div className="space-y-3 pt-4 border-t border-slate-50">
                <div className="flex items-center gap-3 text-slate-500 font-bold text-xs">
                  <Clock size={16} className="text-slate-400" />
                  <span>{new Date(event.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })} at {event.time}</span>
                </div>
                <div className="flex items-center gap-3 text-slate-500 font-bold text-xs">
                  <MapPin size={16} className="text-slate-400" />
                  <span>{event.location}</span>
                </div>
              </div>
            </div>
          ))}
