import React, { useState, useEffect } from 'react';
import { Plus, Waves, X, Loader2, Download, Printer, User, Calendar, CheckCircle } from 'lucide-react';
import { jsPDF } from 'jspdf';

const Baptism: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    fullName: '',
    baptismDate: '',
    officiatedBy: '',
    location: 'Main Sanctuary',
    status: 'COMPLETED'
  });

  useEffect(() => {
    fetchLogs();
  }, []);

  const fetchLogs = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getBaptisms();
    setLogs(res);
    setLoading(false);
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addBaptism(formData);
    setShowModal(false);
    setFormData({ fullName: '', baptismDate: '', officiatedBy: '', location: 'Main Sanctuary', status: 'COMPLETED' });
    fetchLogs();
  };

  const printCertificate = (log: any) => {
    const doc = new jsPDF({ orientation: 'landscape' });
    doc.setFontSize(40);
    doc.setTextColor(79, 70, 229); // Indigo-600
    doc.text('Baptism Certificate', 148, 50, { align: 'center' });

    doc.setFontSize(18);
    doc.setTextColor(0, 0, 0);
    doc.text('This is to certify that', 148, 80, { align: 'center' });

    doc.setFontSize(30);
    doc.setFont('helvetica', 'bold');
    doc.text(log.fullName, 148, 100, { align: 'center' });

    doc.setFontSize(18);
    doc.setFont('helvetica', 'normal');
    doc.text('was baptized in the name of the Father, the Son, and the Holy Spirit on', 148, 120, { align: 'center' });

    doc.setFontSize(22);
    doc.text(new Date(log.baptismDate).toLocaleDateString('en-US', { dateStyle: 'long' }), 148, 140, { align: 'center' });

    doc.setFontSize(14);
    doc.text(`Officiated by: ${log.officiatedBy}`, 148, 170, { align: 'center' });
    doc.text(`Location: ${log.location}`, 148, 180, { align: 'center' });

    doc.save(`baptism_cert_${log.fullName.replace(/\s+/g, '_')}.pdf`);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Baptismal Records</h2>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Registry of public confession of faith</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-2 bg-slate-900 hover:bg-black text-white font-bold py-3 px-6 rounded-2xl shadow-xl transition-all"
        >
          <Plus size={18} />
          <span>Register Candidate</span>
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          <div className="col-span-full py-20 text-center text-slate-400">
            <Loader2 className="animate-spin inline mr-2" /> Loading records...
          </div>
        ) : logs.length === 0 ? (
          <div className="col-span-full bg-white p-20 rounded-[2.5rem] border border-slate-100 text-center">
            <Waves size={48} className="text-slate-200 mx-auto mb-4" />
            <p className="font-black text-slate-400">No baptismal records found.</p>
          </div>
        ) : logs.map((log) => (
          <div key={log.id} className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm group">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-sky-50 text-sky-600 flex items-center justify-center">
                <Waves size={24} />
              </div>
              <button 
                onClick={() => printCertificate(log)}
                className="p-2 bg-slate-50 text-slate-400 hover:bg-indigo-600 hover:text-white rounded-xl transition-all tooltip"
                title="Print Certificate"
              >
                <Printer size={18} />
              </button>
            </div>
            <h3 className="text-lg font-black text-slate-900 mb-1">{log.fullName}</h3>
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-6">Baptized Member</p>

            <div className="space-y-3 pt-4 border-t border-slate-50">
              <div className="flex items-center gap-3 text-slate-500 font-bold text-xs">
                <Calendar size={14} className="text-slate-300" />
                <span>{new Date(log.baptismDate).toLocaleDateString()}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-500 font-bold text-xs">
                <CheckCircle size={14} className="text-slate-300" />
                <span>By: {log.officiatedBy}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between">
              <h3 className="text-xl font-black text-slate-900">New Baptism Entry</h3>
              <button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X size={24} className="text-slate-400" />
              </button>
            </div>
            <form onSubmit={handleAdd} className="p-8 space-y-5">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Candidate Name</label>
                <input required type="text" value={formData.fullName} onChange={(e) => setFormData({...formData, fullName: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black" placeholder="Full name of person" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Baptism Date</label>
                  <input required type="date" value={formData.baptismDate} onChange={(e) => setFormData({...formData, baptismDate: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black" />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Status</label>
                  <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black">
                    <option value="COMPLETED">Completed</option>
                    <option value="SCHEDULED">Scheduled</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Officiated By</label>
                <input required type="text" value={formData.officiatedBy} onChange={(e) => setFormData({...formData, officiatedBy: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black" placeholder="Pastor's Name" />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl hover:bg-black transition-all">Save Entry</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Baptism;

import React, { useState, useEffect } from 'react';
import { HeartHandshake, Plus, X, Loader2, MessageCircle, Phone, Calendar, User, CheckCircle, Clock } from 'lucide-react';

const PastoralCare: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [activeTab, setActiveTab] = useState<'CONVERT' | 'PRAYER' | 'VISITOR'>('CONVERT');
  const [formData, setFormData] = useState({
    fullName: '',
    phone: '',
    type: 'CONVERT' as 'CONVERT' | 'PRAYER' | 'VISITOR',
    notes: '',
    status: 'PENDING'
  });

  useEffect(() => {
    fetchLogs();
  }, []);

  const fetchLogs = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getPastoralCare();
    setLogs(res);
    setLoading(false);
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addPastoralRecord({...formData, type: activeTab});
    setShowModal(false);
    setFormData({ fullName: '', phone: '', type: activeTab, notes: '', status: 'PENDING' });
    fetchLogs();
  };

  const openWhatsApp = (log: any) => {
    let message = "";
    if (log.type === 'CONVERT') message = `Hi ${log.fullName}, we are so excited about your decision to follow Christ! We are here to support you in your new journey. Welcome to the family!`;
    if (log.type === 'VISITOR') message = `Hi ${log.fullName}, it was a blessing having you at our service! We hope you felt the love of God. We'd love to see you again soon.`;
    if (log.type === 'PRAYER') message = `Hi ${log.fullName}, we received your prayer request and our intercessory team is lifting you up today. God bless you!`;

    const url = `https://wa.me/${log.phone.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const filteredLogs = logs.filter(l => l.type === activeTab);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Pastoral Care</h2>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Caring for the flock and new additions</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-2 bg-slate-900 hover:bg-black text-white font-bold py-3 px-6 rounded-2xl shadow-xl transition-all"
        >
          <Plus size={18} />
          <span>Add Record</span>
        </button>
      </div>

      <div className="flex gap-2 p-1.5 bg-white border border-slate-100 rounded-3xl w-fit shadow-sm">
        {(['CONVERT', 'VISITOR', 'PRAYER'] as const).map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${
              activeTab === tab ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'
            }`}
          >
            {tab === 'CONVERT' ? 'New Converts' : tab === 'PRAYER' ? 'Prayer Requests' : 'First Timers'}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          <div className="col-span-full py-20 text-center text-slate-400">
            <Loader2 className="animate-spin inline mr-2" /> Loading care logs...
          </div>
        ) : filteredLogs.length === 0 ? (
          <div className="col-span-full bg-white p-20 rounded-[2.5rem] border border-slate-100 text-center">
            <HeartHandshake size={48} className="text-slate-200 mx-auto mb-4" />
            <p className="font-black text-slate-400 italic">No {activeTab.toLowerCase()} records yet.</p>
          </div>
        ) : filteredLogs.map((log) => (
          <div key={log.id} className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm group">
            <div className="flex justify-between items-start mb-6">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-2xl bg-slate-100 flex items-center justify-center text-slate-400 group-hover:bg-indigo-100 group-hover:text-indigo-600 transition-colors">
                  <User size={20} />
                </div>
                <div>
                  <h3 className="font-black text-slate-800 leading-none">{log.fullName}</h3>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">{log.phone}</span>
                </div>
              </div>
              <button 
                onClick={() => openWhatsApp(log)}
                className="w-10 h-10 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center hover:bg-emerald-600 hover:text-white transition-all shadow-sm shadow-emerald-100"
              >
                <MessageCircle size={18} />
              </button>
            </div>

            <div className="bg-slate-50/50 p-4 rounded-2xl mb-6">
              <p className="text-xs text-slate-600 font-bold leading-relaxed">{log.notes || 'No specific notes added.'}</p>
            </div>

            <div className="flex items-center justify-between pt-4 border-t border-slate-50">
              <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase">
                <Clock size={14} /> 
                <span>{new Date(log.createdAt).toLocaleDateString()}</span>
              </div>
              <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                log.status === 'COMPLETED' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'
              }`}>
                {log.status}
              </span>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between">
              <h3 className="text-xl font-black text-slate-900">Pastoral Registration</h3>
              <button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X size={24} className="text-slate-400" />
              </button>
            </div>
            <form onSubmit={handleAdd} className="p-8 space-y-5">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Name</label>
                <input required type="text" value={formData.fullName} onChange={(e) => setFormData({...formData, fullName: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black" />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Contact Phone</label>
                <input required type="text" value={formData.phone} onChange={(e) => setFormData({...formData, phone: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black" />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Pastoral Notes / Request</label>
                <textarea rows={3} value={formData.notes} onChange={(e) => setFormData({...formData, notes: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black resize-none" />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl hover:bg-black transition-all">Submit Log</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

