import React, { useState, useEffect } from 'react';
import { Wallet, Search, Plus, Filter, FileSpreadsheet, X, Loader2, DollarSign, MessageCircle } from 'lucide-react';
import * as XLSX from 'xlsx';

const Finances: React.FC = () => {
  const [finances, setFinances] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    type: 'OFFERING',
    memberId: '',
    memberPhone: ''
  });

  useEffect(() => {
    fetchFinances();
  }, []);

  const fetchFinances = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getFinances();
    setFinances(res);
    setLoading(false);
  };

  const handleAddFinance = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addFinance({
      ...formData,
      amount: parseFloat(formData.amount)
    });
    setShowModal(false);
    setFormData({ description: '', amount: '', type: 'OFFERING', memberId: '', memberPhone: '' });
    fetchFinances();
  };

  const sendWhatsAppReceipt = (f: any) => {
    const phone = f.memberPhone || "";
    if (!phone) {
      alert("No phone number linked to this transaction.");
      return;
    }
    const message = `Praise God! We have received your ${f.type.toLowerCase()} of KES ${f.amount.toLocaleString()} for ${f.description || 'Church Development'}. May the Lord bless you abundantly. God bless!`;
    const url = `https://wa.me/${phone.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const exportExcel = () => {
    const data = finances.map(f => ({
      Date: new Date(f.date).toLocaleDateString(),
      Description: f.description,
      Type: f.type,
      'Amount (KES)': f.amount,
      Member: f.member?.fullName || 'Anonymous'
    }));

    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Finances");
    XLSX.writeFile(wb, "church_finances_kes.xlsx");
  };

  const totals = finances.reduce((acc, f) => {
    if (f.type === 'EXPENSE') acc.expenses += f.amount;
    else acc.income += f.amount;
    return acc;
  }, { income: 0, expenses: 0 });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Treasury Management</h2>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Financial stewardship in KES</p>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={exportExcel}
            className="flex items-center gap-2 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 font-bold py-3 px-6 rounded-2xl transition-all"
          >
            <FileSpreadsheet size={18} />
            <span>Export (KES)</span>
          </button>
          <button 
            onClick={() => setShowModal(true)}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white font-black py-3 px-6 rounded-2xl shadow-xl shadow-indigo-100 transition-all"
          >
            <Plus size={18} />
            <span>Record KES</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Net Balance</p>
          <p className="text-3xl font-black text-slate-900">KES {(totals.income - totals.expenses).toLocaleString()}</p>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm border-l-4 border-l-emerald-500">
          <p className="text-[10px] font-black text-emerald-500 uppercase tracking-[0.2em] mb-1">Total Revenue</p>
          <p className="text-2xl font-black text-slate-900">KES {totals.income.toLocaleString()}</p>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm border-l-4 border-l-rose-500">
          <p className="text-[10px] font-black text-rose-500 uppercase tracking-[0.2em] mb-1">Total Expenses</p>
          <p className="text-2xl font-black text-slate-900">KES {totals.expenses.toLocaleString()}</p>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100">
                <th className="px-8 py-5">Date</th>
                <th className="px-8 py-5">Source / Purpose</th>
                <th className="px-8 py-5">Type</th>
                <th className="px-8 py-5 text-right">Amount (KES)</th>
                <th className="px-8 py-5 text-right">Receipt</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {loading ? (
                <tr><td colSpan={5} className="p-12 text-center text-slate-300 font-bold"><Loader2 className="animate-spin inline mr-2" /> Loading ledger...</td></tr>
              ) : finances.length === 0 ? (
                <tr><td colSpan={5} className="p-16 text-center text-slate-400 font-bold italic">No financial transactions recorded.</td></tr>
              ) : finances.map((f) => (
                <tr key={f.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-8 py-5 text-xs font-bold text-slate-500 uppercase">
                    {new Date(f.date).toLocaleDateString('en-KE')}
