                  <td className="px-8 py-5">
                    <p className="text-slate-900 font-black">{f.description || 'General Fund'}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{f.member?.fullName || 'Anonymous'}</p>
                  </td>
                  <td className="px-8 py-5">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${
