import React, { useState, useEffect } from 'react';
import { Search, Plus, User, Mail, Phone, MapPin, Briefcase, X, Download, Loader2, MessageCircle } from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

const Members: React.FC = () => {
  const [members, setMembers] = useState<any[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: '',
    gender: 'MALE',
    dob: '',
    address: '',
    ministry: '',
    branch: 'Main Branch',
    status: 'ACTIVE'
  });

  useEffect(() => {
    fetchMembers();
  }, [search]);

  const fetchMembers = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getMembers(search);
    setMembers(res);
    setLoading(false);
  };

  const handleAddMember = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addMember(formData);
    setShowModal(false);
    setFormData({
      fullName: '', email: '', phone: '', gender: 'MALE', 
      dob: '', address: '', ministry: '', branch: 'Main Branch', status: 'ACTIVE'
    });
