    const doc = new jsPDF();
    doc.setFontSize(20);
    doc.text('Church Member Directory', 14, 22);
    const tableData = members.map(m => [m.fullName, m.email, m.phone, m.ministry || 'N/A', m.status]);
    (doc as any).autoTable({
      startY: 35,
      head: [['Full Name', 'Email', 'Phone', 'Ministry', 'Status']],
      body: tableData,
      headStyles: { fillColor: [79, 70, 229] },
      theme: 'grid'
    });
    doc.save('church_members_kes.pdf');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Congregation Directory</h2>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Manage all church members and leaders</p>
