import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import App from './App';
import Login from './pages/Login';

// --- MOCK API FALLBACK (Local Storage) ---
if (typeof (window as any).api === 'undefined') {
  console.warn("Electron API not found. Falling back to Local Storage mode.");

  (window as any).api = {
    register: async (data: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      if (users.find((u: any) => u.email === data.email)) return { error: 'Email already exists' };
      const newUser = { ...data, id: Math.random().toString(36).substr(2, 9) };
      users.push(newUser);
      localStorage.setItem('cms_users', JSON.stringify(users));
      return { user: newUser };
    },
    login: async (credentials: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      const user = users.find((u: any) => u.email === credentials.email && u.password === credentials.password);
      if (!user) return { error: 'Invalid credentials or user not found' };
      return { user };
    },
    getStats: async () => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const income = finances.filter((f: any) => f.type !== 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      const expenses = finances.filter((f: any) => f.type === 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      return { members: members.length, visitors: JSON.parse(localStorage.getItem('cms_pastoral') || '[]').length, totalIncome: income, totalExpenses: expenses };
    },
    getMembers: async (query: string) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      return members.filter((m: any) => m.fullName.toLowerCase().includes(query.toLowerCase()));
    },
    addMember: async (data: any) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const newMember = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      members.push(newMember);
      localStorage.setItem('cms_members', JSON.stringify(members));
      return newMember;
    },
    getFinances: async () => JSON.parse(localStorage.getItem('cms_finances') || '[]'),
    addFinance: async (data: any) => {
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const newFinance = { ...data, id: Math.random().toString(36).substr(2, 9), date: new Date() };
      finances.push(newFinance);
      localStorage.setItem('cms_finances', JSON.stringify(finances));
      return newFinance;
    },
    getEvents: async () => JSON.parse(localStorage.getItem('cms_events') || '[]'),
    addEvent: async (data: any) => {
      const events = JSON.parse(localStorage.getItem('cms_events') || '[]');
      const newEvent = { ...data, id: Math.random().toString(36).substr(2, 9) };
      events.push(newEvent);
      localStorage.setItem('cms_events', JSON.stringify(events));
      return newEvent;
    },
    getBaptisms: async () => JSON.parse(localStorage.getItem('cms_baptisms') || '[]'),
    addBaptism: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_baptisms') || '[]');
      const settings = JSON.parse(localStorage.getItem('cms_settings') || '{}');

      // Generate Member ID: CHURCHPREFIX-YEAR-SEQUENCE
      const prefix = (settings.churchName || 'CHURCH').substring(0, 3).toUpperCase();
      const year = new Date().getFullYear();
      const seq = (logs.length + 1).toString().padStart(4, '0');
      const generatedId = `${prefix}-${year}-${seq}`;

      const newLog = { ...data, memberId: generatedId, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      logs.push(newLog);
      localStorage.setItem('cms_baptisms', JSON.stringify(logs));

      // Also update the member record if it exists
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const memberIndex = members.findIndex((m: any) => m.fullName.toLowerCase() === data.fullName.toLowerCase());
      if (memberIndex > -1) {
        members[memberIndex].memberId = generatedId;
        localStorage.setItem('cms_members', JSON.stringify(members));
      }

      return newLog;
    },
    getPastoralCare: async () => JSON.parse(localStorage.getItem('cms_pastoral') || '[]'),
    addPastoralRecord: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_pastoral') || '[]');
      const newLog = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      logs.push(newLog);
      localStorage.setItem('cms_pastoral', JSON.stringify(logs));
      return newLog;
    },
    getAttendance: async () => JSON.parse(localStorage.getItem('cms_attendance') || '[]'),
    saveAttendance: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_attendance') || '[]');
      const newLog = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      logs.push(newLog);
      localStorage.setItem('cms_attendance', JSON.stringify(logs));
      return newLog;
    },
    getSettings: async () => JSON.parse(localStorage.getItem('cms_settings') || '{"churchName": "Nairobi Hope Chapel", "branch": "Westlands Branch", "currency": "KES", "logo": ""}'),
    updateSettings: async (data: any) => {
      localStorage.setItem('cms_settings', JSON.stringify(data));
      return data;
    },
    backupDatabase: async () => {
      const allData = {
        users: JSON.parse(localStorage.getItem('cms_users') || '[]'),
        members: JSON.parse(localStorage.getItem('cms_members') || '[]'),
        finances: JSON.parse(localStorage.getItem('cms_finances') || '[]'),
        events: JSON.parse(localStorage.getItem('cms_events') || '[]'),
        baptisms: JSON.parse(localStorage.getItem('cms_baptisms') || '[]'),
        pastoral: JSON.parse(localStorage.getItem('cms_pastoral') || '[]'),
        attendance: JSON.parse(localStorage.getItem('cms_attendance') || '[]'),
        settings: JSON.parse(localStorage.getItem('cms_settings') || '{}'),
      };
      const blob = new Blob([JSON.stringify(allData)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `ChurchManager_Export_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
      return { success: true };
    },
    importDatabase: async (jsonString: string) => {
      try {
        const data = JSON.parse(jsonString);
        if (data.users) localStorage.setItem('cms_users', JSON.stringify(data.users));
        if (data.members) localStorage.setItem('cms_members', JSON.stringify(data.members));
        if (data.finances) localStorage.setItem('cms_finances', JSON.stringify(data.finances));
        if (data.events) localStorage.setItem('cms_events', JSON.stringify(data.events));
        if (data.baptisms) localStorage.setItem('cms_baptisms', JSON.stringify(data.baptisms));
        if (data.pastoral) localStorage.setItem('cms_pastoral', JSON.stringify(data.pastoral));
        if (data.attendance) localStorage.setItem('cms_attendance', JSON.stringify(data.attendance));
        if (data.settings) localStorage.setItem('cms_settings', JSON.stringify(data.settings));
        return { success: true };
      } catch (e) {
        return { success: false, error: 'Invalid backup file' };
      }
    }
  };
}

const Root = () => {
  const [user, setUser] = React.useState<any>(() => {
    const saved = localStorage.getItem('cms_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const handleLogin = (userData: any) => {
    setUser(userData);
    localStorage.setItem('cms_current_user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('cms_current_user');
  };

  const isAuthenticated = !!user;

  return (
    <Router>
      <Routes>
        <Route 
          path="/login" 
          element={isAuthenticated ? <Navigate to="/" replace /> : <Login onLogin={handleLogin} />} 
        />
        <Route 
          path="/*" 
          element={isAuthenticated ? <App user={user} onLogout={handleLogout} /> : <Navigate to="/login" replace />} 
        />
      </Routes>
    </Router>
  );
};

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error("Root element not found");
const root = ReactDOM.createRoot(rootElement);
root.render(<Root />);

import React, { useState, useEffect, useRef } from 'react';
import { Settings as SettingsIcon, Church, MapPin, Database, Save, Loader2, ShieldCheck, RefreshCw, Upload, DownloadCloud, Image as ImageIcon } from 'lucide-react';

const Settings: React.FC = () => {
  const [settings, setSettings] = useState({
    churchName: '',
    branch: '',
    phone: '',
    address: '',
    currency: 'KES',
    logo: ''
  });
  const [loading, setLoading] = useState(false);
  const [backingUp, setBackingUp] = useState(false);
  const [importing, setImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    const api = (window as any).api;
    const data = await api.getSettings();
    setSettings(data);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const api = (window as any).api;
    await api.updateSettings(settings);
    setLoading(false);
    alert('Settings updated successfully!');
  };

  const handleBackup = async () => {
    setBackingUp(true);
    const api = (window as any).api;
    await api.backupDatabase();
    setBackingUp(false);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setImporting(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const content = event.target?.result as string;
      const api = (window as any).api;
      const res = await api.importDatabase(content);
      if (res.success) {
        alert('Database imported successfully! Application will refresh.');
        window.location.reload();
      } else {
        alert('Import failed: ' + res.error);
      }
      setImporting(false);
    };
    reader.readAsText(file);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      setSettings({ ...settings, logo: base64 });
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-12 animate-in fade-in duration-500">
      <div>
        <h2 className="text-2xl font-black text-slate-900 tracking-tight">System Settings</h2>
        <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Configure ChMS details and Data Tools</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="md:col-span-2 space-y-8">
          <div className="bg-white rounded-[3rem] border border-slate-100 p-10 shadow-sm">
            <div className="flex items-center gap-3 mb-10">
              <div className="w-12 h-12 rounded-[1.5rem] bg-indigo-50 text-indigo-600 flex items-center justify-center">
                <Church size={24} />
              </div>
              <h3 className="text-xl font-black text-slate-900 tracking-tight">Church Profile</h3>
            </div>

            <div className="mb-10 flex flex-col items-center">
              <div className="relative group">
                <div className="w-32 h-32 rounded-3xl bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden transition-all group-hover:border-indigo-400">
                  {settings.logo ? (
                    <img src={settings.logo} alt="Church Logo" className="w-full h-full object-cover" />
                  ) : (
                    <ImageIcon size={40} className="text-slate-300" />
                  )}
                  <button 
                    onClick={() => logoInputRef.current?.click()}
                    className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white"
                  >
                    <Upload size={24} />
                  </button>
                </div>
                <input 
                  type="file" 
                  ref={logoInputRef} 
                  className="hidden" 
                  accept="image/*" 
                  onChange={handleLogoUpload} 
                />
              </div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-4">Church Logo</p>
            </div>

            <form onSubmit={handleSave} className="space-y-8">
              <div className="grid grid-cols-2 gap-6">
                <div className="col-span-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Official Church Name</label>
                  <input type="text" value={settings.churchName} onChange={(e) => setSettings({...settings, churchName: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:border-indigo-600 outline-none transition-all font-bold text-black" />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Branch / Station</label>
                  <input type="text" value={settings.branch} onChange={(e) => setSettings({...settings, branch: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:border-indigo-600 outline-none transition-all font-bold text-black" />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">System Currency</label>
                  <select disabled className="w-full px-6 py-5 bg-slate-100 border-2 border-slate-100 rounded-[1.5rem] font-black text-slate-400 appearance-none">
                    <option value="KES">Kenyan Shilling (KES)</option>
                  </select>
                </div>
                <div className="col-span-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Physical Location (Kenya)</label>
                  <input type="text" value={settings.address} onChange={(e) => setSettings({...settings, address: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:border-indigo-600 outline-none transition-all font-bold text-black" placeholder="e.g. Off Ngong Road, Nairobi" />
                </div>
              </div>
              <button type="submit" disabled={loading} className="w-full flex items-center justify-center gap-3 bg-slate-900 hover:bg-black text-white font-black py-6 rounded-[1.8rem] shadow-2xl transition-all disabled:opacity-50">
                {loading ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} />}
                <span>Update Global Settings</span>
              </button>
            </form>
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-white rounded-[3rem] border border-slate-100 p-10 shadow-sm">
            <div className="flex items-center gap-3 mb-8">
              <div className="w-12 h-12 rounded-[1.5rem] bg-emerald-50 text-emerald-600 flex items-center justify-center">
                <Database size={24} />
              </div>
              <h3 className="text-xl font-black text-slate-900 tracking-tight">Data Management</h3>
            </div>
            <p className="text-sm text-slate-400 font-bold mb-8 leading-relaxed">Migrate your data between devices using these tools.</p>

            <div className="space-y-4">
              <button 
                onClick={handleBackup} 
                disabled={backingUp}
                className="w-full flex items-center justify-center gap-3 bg-emerald-50 hover:bg-emerald-100 text-emerald-700 font-black py-5 rounded-[1.5rem] transition-all border border-emerald-200"
              >
                {backingUp ? <Loader2 className="animate-spin" size={20} /> : <RefreshCw size={20} />}
                <span>Export ChMS Backup</span>
              </button>

              <button 
                onClick={handleImportClick}
                disabled={importing}
                className="w-full flex items-center justify-center gap-3 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-black py-5 rounded-[1.5rem] transition-all border border-indigo-200"
              >
                {importing ? <Loader2 className="animate-spin" size={20} /> : <DownloadCloud size={20} />}
                <span>Import ChMS Data</span>
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept=".json,.db" 
                onChange={handleFileImport} 
              />
            </div>
          </div>

          <div className="bg-slate-900 rounded-[3rem] p-10 text-white shadow-2xl shadow-indigo-100 border border-slate-800">
            <div className="flex items-center gap-3 mb-8">
              <ShieldCheck size={28} className="text-indigo-400" />
              <h3 className="text-xl font-black tracking-tight">Security Core</h3>
            </div>
            <div className="space-y-5">
              <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-slate-500">
                <span>Encryption</span>
                <span className="text-emerald-400">RSA-2048</span>
              </div>
              <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-slate-500">
                <span>Auto-Backup</span>
                <span className="text-emerald-400">ENABLED</span>
              </div>
              <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-slate-500">
                <span>Role Validation</span>
                <span className="text-emerald-400">ACTIVE</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { Plus, Waves, X, Loader2, Download, Printer, User, Calendar, CheckCircle, Hash } from 'lucide-react';
import { jsPDF } from 'jspdf';

const Baptism: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [churchInfo, setChurchInfo] = useState<any>(null);
  const [formData, setFormData] = useState({
    fullName: '',
    baptismDate: '',
    officiatedBy: '',
    location: 'Main Sanctuary',
    status: 'COMPLETED'
  });

  useEffect(() => {
    fetchLogs();
    fetchChurchInfo();
  }, []);

  const fetchChurchInfo = async () => {
    const api = (window as any).api;
    const info = await api.getSettings();
    setChurchInfo(info);
  };

  const fetchLogs = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getBaptisms();
    setLogs(res);
    setLoading(false);
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addBaptism(formData);
    setShowModal(false);
    setFormData({ fullName: '', baptismDate: '', officiatedBy: '', location: 'Main Sanctuary', status: 'COMPLETED' });
    fetchLogs();
  };

  const printCertificate = (log: any) => {
    const doc = new jsPDF({ orientation: 'landscape' });

    // Add church logo if exists
    if (churchInfo?.logo) {
      try {
        doc.addImage(churchInfo.logo, 'PNG', 133, 10, 30, 30);
      } catch (e) {
        console.warn("Logo print failed", e);
      }
    }

    doc.setFontSize(40);
    doc.setTextColor(79, 70, 229); // Indigo-600
    doc.text('Baptism Certificate', 148, 55, { align: 'center' });

    doc.setFontSize(14);
    doc.setTextColor(148, 163, 184);
    doc.text(`MEMBER ID: ${log.memberId}`, 148, 65, { align: 'center' });

    doc.setFontSize(18);
    doc.setTextColor(0, 0, 0);
    doc.text('This is to certify that', 148, 85, { align: 'center' });

    doc.setFontSize(30);
    doc.setFont('helvetica', 'bold');
    doc.text(log.fullName, 148, 105, { align: 'center' });

    doc.setFontSize(18);
    doc.setFont('helvetica', 'normal');
    doc.text('was baptized in the name of the Father, the Son, and the Holy Spirit on', 148, 125, { align: 'center' });

    doc.setFontSize(22);
    doc.text(new Date(log.baptismDate).toLocaleDateString('en-US', { dateStyle: 'long' }), 148, 145, { align: 'center' });

    doc.setFontSize(14);
    doc.text(`Officiated by: ${log.officiatedBy}`, 148, 175, { align: 'center' });
    doc.text(`at ${churchInfo?.churchName || 'The Sanctuary'}`, 148, 185, { align: 'center' });

    doc.save(`baptism_cert_${log.fullName.replace(/\s+/g, '_')}.pdf`);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Baptismal Records</h2>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Registry of public confession of faith</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-2 bg-slate-900 hover:bg-black text-white font-bold py-3 px-6 rounded-2xl shadow-xl transition-all"
        >
          <Plus size={18} />
          <span>Register Candidate</span>
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          <div className="col-span-full py-20 text-center text-slate-400">
            <Loader2 className="animate-spin inline mr-2" /> Loading records...
          </div>
        ) : logs.length === 0 ? (
          <div className="col-span-full bg-white p-20 rounded-[2.5rem] border border-slate-100 text-center">
            <Waves size={48} className="text-slate-200 mx-auto mb-4" />
            <p className="font-black text-slate-400">No baptismal records found.</p>
          </div>
        ) : logs.map((log) => (
          <div key={log.id} className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm group">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-sky-50 text-sky-600 flex items-center justify-center">
                <Waves size={24} />
              </div>
              <button 
                onClick={() => printCertificate(log)}
                className="p-2 bg-slate-50 text-slate-400 hover:bg-indigo-600 hover:text-white rounded-xl transition-all tooltip"
                title="Print Certificate"
              >
                <Printer size={18} />
              </button>
            </div>
            <h3 className="text-lg font-black text-slate-900 mb-1">{log.fullName}</h3>
            <div className="flex items-center gap-1 mb-6">
              <Hash size={12} className="text-indigo-600" />
              <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{log.memberId}</p>
            </div>

            <div className="space-y-3 pt-4 border-t border-slate-50">
              <div className="flex items-center gap-3 text-slate-500 font-bold text-xs">
                <Calendar size={14} className="text-slate-300" />
                <span>{new Date(log.baptismDate).toLocaleDateString()}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-500 font-bold text-xs">
                <CheckCircle size={14} className="text-slate-300" />
                <span>By: {log.officiatedBy}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between">
              <h3 className="text-xl font-black text-slate-900">New Baptism Entry</h3>
              <button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X size={24} className="text-slate-400" />
              </button>
            </div>
            <form onSubmit={handleAdd} className="p-8 space-y-5">
              <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100">
                <p className="text-[10px] font-bold text-amber-700 uppercase leading-relaxed">
                  Note: A permanent Member ID will be automatically generated upon saving this baptism record.
                </p>
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Candidate Name</label>
                <input required type="text" value={formData.fullName} onChange={(e) => setFormData({...formData, fullName: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black" placeholder="Full name of person" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Baptism Date</label>
                  <input required type="date" value={formData.baptismDate} onChange={(e) => setFormData({...formData, baptismDate: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black" />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Status</label>
                  <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black">
                    <option value="COMPLETED">Completed</option>
                    <option value="SCHEDULED">Scheduled</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Officiated By</label>
                <input required type="text" value={formData.officiatedBy} onChange={(e) => setFormData({...formData, officiatedBy: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold text-black" placeholder="Pastor's Name" />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl hover:bg-black transition-all">Save & Generate ID</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Baptism;

import React, { useState, useEffect } from 'react';
import { Search, Plus, User, Mail, Phone, MapPin, Briefcase, X, Download, Loader2, MessageCircle, Hash } from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

const Members: React.FC = () => {
  const [members, setMembers] = useState<any[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: '',
    gender: 'MALE',
    dob: '',
    address: '',
    ministry: '',
    branch: 'Main Branch',
    status: 'ACTIVE'
  });

  useEffect(() => {
    fetchMembers();
  }, [search]);

  const fetchMembers = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getMembers(search);
    setMembers(res);
    setLoading(false);
  };

  const handleAddMember = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addMember(formData);
    setShowModal(false);
    setFormData({
      fullName: '', email: '', phone: '', gender: 'MALE', 
      dob: '', address: '', ministry: '', branch: 'Main Branch', status: 'ACTIVE'
    });
    fetchMembers();
  };

  const openWhatsApp = (m: any) => {
    const url = `https://wa.me/${m.phone.replace(/\D/g, '')}?text=${encodeURIComponent(`Greetings ${m.fullName}, we hope you're having a blessed day!`)}`;
    window.open(url, '_blank');
  };

  const exportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(20);
    doc.text('Church Member Directory', 14, 22);
    const tableData = members.map(m => [m.memberId || 'PENDING', m.fullName, m.email, m.phone, m.ministry || 'N/A', m.status]);
    (doc as any).autoTable({
      startY: 35,
      head: [['ID', 'Full Name', 'Email', 'Phone', 'Ministry', 'Status']],
      body: tableData,
      headStyles: { fillColor: [79, 70, 229] },
      theme: 'grid'
    });
    doc.save('church_members_kes.pdf');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Congregation Directory</h2>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Manage all church members and leaders</p>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={exportPDF} className="flex items-center gap-2 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 font-bold py-3 px-6 rounded-2xl transition-all shadow-sm">
            <Download size={18} />
            <span>Export PDF</span>
          </button>
          <button onClick={() => setShowModal(true)} className="flex items-center gap-2 bg-slate-900 hover:bg-black text-white font-black py-3 px-6 rounded-2xl shadow-xl transition-all">
            <Plus size={18} />
            <span>Add Member</span>
          </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="relative">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search by name, contact or location..."
            className="w-full pl-14 pr-4 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none transition-all font-bold text-black"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100">
                <th className="px-8 py-5">Member</th>
                <th className="px-8 py-5">Contact Info</th>
                <th className="px-8 py-5 text-center">ID / Dept</th>
                <th className="px-8 py-5 text-center">Status</th>
                <th className="px-8 py-5 text-right">Reach Out</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {loading ? (
                <tr><td colSpan={5} className="p-12 text-center text-slate-300 font-bold"><Loader2 className="animate-spin inline mr-2" /> Syncing database...</td></tr>
              ) : members.length === 0 ? (
                <tr><td colSpan={5} className="p-16 text-center text-slate-400 font-bold italic">No members found matching your search.</td></tr>
              ) : members.map((m) => (
                <tr key={m.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-slate-100 flex items-center justify-center text-slate-400 group-hover:bg-indigo-100 group-hover:text-indigo-600 transition-all font-black">
                        {m.fullName.charAt(0)}
                      </div>
                      <div>
                        <p className="font-black text-slate-900 leading-none">{m.fullName}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-1 tracking-wider">{m.branch}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2 text-slate-500 text-xs font-bold">
                        <Mail size={14} className="text-slate-300" /> <span>{m.email}</span>
                      </div>
