import React, { useState, useEffect } from 'react';
import { Plus, Waves, X, Loader2, Printer, Calendar, CheckCircle, Hash, IdCard } from 'lucide-react';
import { jsPDF } from 'jspdf';

const Baptism: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [churchInfo, setChurchInfo] = useState<any>(null);
  const [formData, setFormData] = useState({
    fullName: '',
    baptismDate: '',
    officiatedBy: '',
    location: 'Main Sanctuary',
    status: 'COMPLETED'
  });

  useEffect(() => {
    fetchLogs();
    fetchChurchInfo();
  }, []);

  const fetchChurchInfo = async () => {
    const api = (window as any).api;
    const info = await api.getSettings();
    setChurchInfo(info);
  };

  const fetchLogs = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getBaptisms();
    setLogs(res);
    setLoading(false);
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addBaptism(formData);
    setShowModal(false);
    setFormData({ fullName: '', baptismDate: '', officiatedBy: '', location: 'Main Sanctuary', status: 'COMPLETED' });
    fetchLogs();
  };

  const printIDCard = (log: any) => {
    // ID-1 Standard Size: 85.60 mm x 53.98 mm
    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: [85.6, 53.98]
    });

    // Background Gradient or Solid Header
    doc.setFillColor(79, 70, 229); // Indigo-600
    doc.rect(0, 0, 85.6, 18, 'F');

    // Church Name
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.text(churchInfo?.churchName?.toUpperCase() || 'CHURCH NAME', 42.8, 8, { align: 'center' });

    doc.setFontSize(5);
    doc.setFont('helvetica', 'normal');
    doc.text(churchInfo?.branch?.toUpperCase() || 'MAIN BRANCH', 42.8, 12, { align: 'center' });

    // Logo Placeholder/Integration
    if (churchInfo?.logo) {
      try {
        doc.addImage(churchInfo.logo, 'PNG', 5, 2, 14, 14);
      } catch (e) {
        console.warn("Logo print failed on card", e);
      }
    }

    // Card Body
    doc.setTextColor(30, 41, 59); // Slate-800
    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    doc.text('MEMBERSHIP CARD', 42.8, 25, { align: 'center' });

    // Divider
    doc.setDrawColor(226, 232, 240);
    doc.line(10, 28, 75.6, 28);

    // Member Info
    doc.setFontSize(7);
    doc.setFont('helvetica', 'bold');
    doc.text('NAME:', 10, 34);
    doc.setFont('helvetica', 'normal');
    doc.text(log.fullName.toUpperCase(), 25, 34);

    doc.setFont('helvetica', 'bold');
    doc.text('ID NO:', 10, 40);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(79, 70, 229);
    doc.text(log.memberId, 25, 40);

    doc.setTextColor(30, 41, 59);
    doc.setFont('helvetica', 'bold');
    doc.text('BAPTIZED:', 10, 46);
    doc.setFont('helvetica', 'normal');
    doc.text(new Date(log.baptismDate).toLocaleDateString(), 25, 46);

    // Footer
    doc.setFillColor(248, 250, 252);
    doc.rect(0, 50, 85.6, 4, 'F');
    doc.setFontSize(4);
    doc.setTextColor(148, 163, 184);
    doc.text('OFFICIALLY ISSUED BY CHURCH ADMINISTRATION', 42.8, 52.5, { align: 'center' });

    doc.save(`member_id_${log.memberId}.pdf`);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Baptismal Records</h2>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Registry of public confession of faith</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-2 bg-slate-900 hover:bg-black text-white font-bold py-3 px-6 rounded-2xl shadow-xl transition-all"
        >
          <Plus size={18} />
          <span>Register Candidate</span>
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          <div className="col-span-full py-20 text-center text-slate-400">
            <Loader2 className="animate-spin inline mr-2" /> Loading records...
          </div>
        ) : logs.length === 0 ? (
          <div className="col-span-full bg-white p-20 rounded-[2.5rem] border border-slate-100 text-center">
            <Waves size={48} className="text-slate-200 mx-auto mb-4" />
            <p className="font-black text-slate-400">No baptismal records found.</p>
          </div>
        ) : logs.map((log) => (
          <div key={log.id} className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm group">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-sky-50 text-sky-600 flex items-center justify-center">
                <Waves size={24} />
              </div>
              <button 
                onClick={() => printIDCard(log)}
                className="p-2 bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white rounded-xl transition-all flex items-center gap-2 font-bold text-[10px]"
                title="Print Member ID Card"
              >
                <IdCard size={16} />
                <span>PRINT ID</span>
