import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import App from './App';
import Login from './pages/Login';

// --- MOCK API FALLBACK (Local Storage) ---
if (typeof (window as any).api === 'undefined') {
  console.warn("Electron API not found. Falling back to Local Storage mode.");

  (window as any).api = {
    register: async (data: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      if (users.find((u: any) => u.email === data.email)) return { error: 'Email already exists' };
      const newUser = { ...data, id: Math.random().toString(36).substr(2, 9) };
      users.push(newUser);
      localStorage.setItem('cms_users', JSON.stringify(users));
      return { user: newUser };
    },
    login: async (credentials: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      const user = users.find((u: any) => u.email === credentials.email && u.password === credentials.password);
      if (!user) return { error: 'Invalid credentials or user not found' };
      return { user };
    },
    getStats: async () => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const income = finances.filter((f: any) => f.type !== 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      const expenses = finances.filter((f: any) => f.type === 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      return { members: members.length, visitors: JSON.parse(localStorage.getItem('cms_pastoral') || '[]').length, totalIncome: income, totalExpenses: expenses };
    },
    getMembers: async (query: string) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      return members.filter((m: any) => m.fullName.toLowerCase().includes(query.toLowerCase()));
    },
    addMember: async (data: any) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const newMember = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      members.push(newMember);
      localStorage.setItem('cms_members', JSON.stringify(members));
      return newMember;
    },
    getFinances: async () => JSON.parse(localStorage.getItem('cms_finances') || '[]'),
    addFinance: async (data: any) => {
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const newFinance = { ...data, id: Math.random().toString(36).substr(2, 9), date: new Date() };
      finances.push(newFinance);
      localStorage.setItem('cms_finances', JSON.stringify(finances));
      return newFinance;
    },
    getEvents: async () => JSON.parse(localStorage.getItem('cms_events') || '[]'),
    addEvent: async (data: any) => {
      const events = JSON.parse(localStorage.getItem('cms_events') || '[]');
      const newEvent = { ...data, id: Math.random().toString(36).substr(2, 9) };
      events.push(newEvent);
      localStorage.setItem('cms_events', JSON.stringify(events));
      return newEvent;
    },
    getBaptisms: async () => JSON.parse(localStorage.getItem('cms_baptisms') || '[]'),
    addBaptism: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_baptisms') || '[]');
      const settings = JSON.parse(localStorage.getItem('cms_settings') || '{}');

      const prefix = (settings.churchName || 'CHURCH').substring(0, 3).toUpperCase();
      const year = new Date().getFullYear();
      const seq = (logs.length + 1).toString().padStart(4, '0');
      const generatedId = `${prefix}-${year}-${seq}`;

      const newLog = { ...data, memberId: generatedId, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      logs.push(newLog);
      localStorage.setItem('cms_baptisms', JSON.stringify(logs));

      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const memberIndex = members.findIndex((m: any) => m.fullName.toLowerCase() === data.fullName.toLowerCase());
      if (memberIndex > -1) {
        members[memberIndex].memberId = generatedId;
        localStorage.setItem('cms_members', JSON.stringify(members));
      }

      return newLog;
    },
    getAnnouncements: async () => JSON.parse(localStorage.getItem('cms_announcements') || '[]'),
    addAnnouncement: async (data: any) => {
      const list = JSON.parse(localStorage.getItem('cms_announcements') || '[]');
      const newItem = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date(), broadcastStatus: 'PENDING' };
      list.push(newItem);
      localStorage.setItem('cms_announcements', JSON.stringify(list));
      return newItem;
    },
    updateAnnouncementStatus: async (id: string, status: string) => {
      const list = JSON.parse(localStorage.getItem('cms_announcements') || '[]');
      const idx = list.findIndex((a: any) => a.id === id);
      if (idx > -1) {
        list[idx].broadcastStatus = status;
        localStorage.setItem('cms_announcements', JSON.stringify(list));
      }
      return { success: true };
    },
    getSettings: async () => JSON.parse(localStorage.getItem('cms_settings') || '{"churchName": "Nairobi Hope Chapel", "branch": "Westlands", "currency": "KES", "logo": "", "messagingProvider": "NONE", "apiKey": ""}'),
    updateSettings: async (data: any) => {
      localStorage.setItem('cms_settings', JSON.stringify(data));
      return data;
    },
    backupDatabase: async () => {
      const allData = {
        users: JSON.parse(localStorage.getItem('cms_users') || '[]'),
        members: JSON.parse(localStorage.getItem('cms_members') || '[]'),
        finances: JSON.parse(localStorage.getItem('cms_finances') || '[]'),
        events: JSON.parse(localStorage.getItem('cms_events') || '[]'),
        baptisms: JSON.parse(localStorage.getItem('cms_baptisms') || '[]'),
        pastoral: JSON.parse(localStorage.getItem('cms_pastoral') || '[]'),
        attendance: JSON.parse(localStorage.getItem('cms_attendance') || '[]'),
        announcements: JSON.parse(localStorage.getItem('cms_announcements') || '[]'),
        settings: JSON.parse(localStorage.getItem('cms_settings') || '{}'),
      };
      const blob = new Blob([JSON.stringify(allData)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `ChurchManager_Export_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
      return { success: true };
    },
    importDatabase: async (jsonString: string) => {
      try {
        const data = JSON.parse(jsonString);
        Object.keys(data).forEach(key => {
          localStorage.setItem(`cms_${key}`, JSON.stringify(data[key]));
        });
        return { success: true };
      } catch (e) {
        return { success: false, error: 'Invalid backup file' };
      }
    }
  };
}

const Root = () => {
  const [user, setUser] = React.useState<any>(() => {
    const saved = localStorage.getItem('cms_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const handleLogin = (userData: any) => {
    setUser(userData);
    localStorage.setItem('cms_current_user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('cms_current_user');
  };

  const isAuthenticated = !!user;

  return (
    <Router>
      <Routes>
        <Route path="/login" element={isAuthenticated ? <Navigate to="/" replace /> : <Login onLogin={handleLogin} />} />
        <Route path="/*" element={isAuthenticated ? <App user={user} onLogout={handleLogout} /> : <Navigate to="/login" replace />} />
      </Routes>
    </Router>
  );
};

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error("Root element not found");
const root = ReactDOM.createRoot(rootElement);
root.render(<Root />);

import React, { useState, useEffect } from 'react';
import { Megaphone, Plus, X, Loader2, MessageCircle, Send, Calendar, Users, Info, CheckCircle, AlertCircle, Clock } from 'lucide-react';

const Announcements: React.FC = () => {
  const [announcements, setAnnouncements] = useState<any[]>([]);
  const [members, setMembers] = useState<any[]>([]);
  const [settings, setSettings] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [showBroadcastCenter, setShowBroadcastCenter] = useState(false);
  const [activeAnnouncement, setActiveAnnouncement] = useState<any>(null);
  const [broadcastQueue, setBroadcastQueue] = useState<any[]>([]);
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  const [formData, setFormData] = useState({
    title: '',
    content: '',
    target: 'ALL_MEMBERS'
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    const api = (window as any).api;
    const [annRes, memRes, settRes] = await Promise.all([
      api.getAnnouncements(),
      api.getMembers(''),
      api.getSettings()
    ]);
    setAnnouncements(annRes);
    setMembers(memRes);
    setSettings(settRes);
    setLoading(false);
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addAnnouncement(formData);
    setShowModal(false);
    setFormData({ title: '', content: '', target: 'ALL_MEMBERS' });
    fetchData();
  };

  const openBroadcastCenter = (ann: any) => {
    setActiveAnnouncement(ann);

    // Filter target members
    let targets = members;
    if (ann.target !== 'ALL_MEMBERS') {
      targets = members.filter(m => m.ministry === ann.target);
    }

    setBroadcastQueue(targets.map(m => ({ ...m, status: 'PENDING' })));
    setShowBroadcastCenter(true);
  };

  const startAutomatedBroadcast = async () => {
    setIsBroadcasting(true);
    const api = (window as any).api;

    // Step-by-step processing to simulate background API calls
    for (let i = 0; i < broadcastQueue.length; i++) {
      setBroadcastQueue(prev => prev.map((item, idx) => idx === i ? { ...item, status: 'SENDING' } : item));

      // Artificial delay to simulate network latency
      await new Promise(resolve => setTimeout(resolve, 800));

      // LOGIC: If an API Key is present in settings, we would actually trigger a background fetch here.
      // Since we are offline, we simulate the 'SUCCESS' based on whether they have a valid phone.
      const hasPhone = broadcastQueue[i].phone && broadcastQueue[i].phone.length > 5;

      setBroadcastQueue(prev => prev.map((item, idx) => idx === i ? { ...item, status: hasPhone ? 'SUCCESS' : 'FAILED' } : item));
    }

    setIsBroadcasting(false);
    await api.updateAnnouncementStatus(activeAnnouncement.id, 'COMPLETED');
    fetchData();
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Church Announcements</h2>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Automated background broadcasting center</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
