import React, { useState, useEffect, useRef } from 'react';
import { Settings as SettingsIcon, Church, MapPin, Database, Save, Loader2, ShieldCheck, RefreshCw, Upload, DownloadCloud, Image as ImageIcon, MessageCircle, Key } from 'lucide-react';

const Settings: React.FC = () => {
  const [settings, setSettings] = useState({
    churchName: '',
    branch: '',
    phone: '',
    address: '',
    currency: 'KES',
    logo: '',
    messagingProvider: 'NONE',
    apiKey: ''
  });
  const [loading, setLoading] = useState(false);
  const [backingUp, setBackingUp] = useState(false);
  const [importing, setImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    const api = (window as any).api;
    const data = await api.getSettings();
    setSettings(data);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const api = (window as any).api;
    await api.updateSettings(settings);
    setLoading(false);
    alert('Settings updated successfully!');
  };

  const handleBackup = async () => {
    setBackingUp(true);
    const api = (window as any).api;
    await api.backupDatabase();
    setBackingUp(false);
  };

  const handleFileImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setImporting(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      const api = (window as any).api;
      const res = await api.importDatabase(event.target?.result as string);
      if (res.success) {
        alert('Database imported! Refreshing app.');
        window.location.reload();
      }
      setImporting(false);
    };
    reader.readAsText(file);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => setSettings({ ...settings, logo: event.target?.result as string });
    reader.readAsDataURL(file);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-12 animate-in fade-in duration-500">
      <div>
        <h2 className="text-2xl font-black text-slate-900 tracking-tight">System Settings</h2>
        <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Global Configuration & API Tools</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="md:col-span-2 space-y-8">
          <div className="bg-white rounded-[3rem] border border-slate-100 p-10 shadow-sm">
            <div className="flex items-center gap-3 mb-10">
              <div className="w-12 h-12 rounded-[1.5rem] bg-indigo-50 text-indigo-600 flex items-center justify-center">
                <Church size={24} />
              </div>
              <h3 className="text-xl font-black text-slate-900 tracking-tight">Church Profile</h3>
            </div>

            <div className="mb-10 flex flex-col items-center">
              <div className="relative group cursor-pointer" onClick={() => logoInputRef.current?.click()}>
                <div className="w-32 h-32 rounded-3xl bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden transition-all group-hover:border-indigo-400">
                  {settings.logo ? (
                    <img src={settings.logo} alt="Logo" className="w-full h-full object-cover" />
                  ) : (
                    <ImageIcon size={40} className="text-slate-300" />
                  )}
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white">
                    <Upload size={24} />
                  </div>
                </div>
                <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
              </div>
              <p className="text-[10px] font-black text-slate-400 uppercase mt-4">Upload Church Seal / Logo</p>
            </div>

            <form onSubmit={handleSave} className="space-y-8">
              <div className="grid grid-cols-2 gap-6">
                <div className="col-span-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Church Name</label>
                  <input type="text" value={settings.churchName} onChange={(e) => setSettings({...settings, churchName: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:border-indigo-600 outline-none font-bold text-black" />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Branch</label>
                  <input type="text" value={settings.branch} onChange={(e) => setSettings({...settings, branch: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:border-indigo-600 outline-none font-bold text-black" />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Currency</label>
                  <select disabled className="w-full px-6 py-5 bg-slate-100 border-2 border-slate-100 rounded-[1.5rem] font-black text-slate-400">
                    <option value="KES">KES (Kenya)</option>
                  </select>
                </div>
              </div>

              <div className="pt-8 border-t border-slate-100">
                <div className="flex items-center gap-3 mb-6">
                  <MessageCircle size={20} className="text-indigo-600" />
                  <h4 className="text-lg font-black text-slate-900 tracking-tight">Messaging Gateway</h4>
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Service Provider</label>
                    <select value={settings.messagingProvider} onChange={(e) => setSettings({...settings, messagingProvider: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:border-indigo-600 outline-none font-bold text-black appearance-none">
                      <option value="NONE">Manual Link (No API)</option>
                      <option value="META">Meta WhatsApp Business API</option>
                      <option value="TWILIO">Twilio SMS/WhatsApp Gateway</option>
                      <option value="AFRICASTALKING">AfricasTalking (KE SMS)</option>
                    </select>
                  </div>
                  {settings.messagingProvider !== 'NONE' && (
                    <div className="col-span-2">
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">API Key / Auth Token</label>
                      <div className="relative">
                        <Key className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                        <input type="password" value={settings.apiKey} onChange={(e) => setSettings({...settings, apiKey: e.target.value})} className="w-full px-12 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:border-indigo-600 outline-none font-bold text-black" placeholder="Enter your provider's secret key" />
                      </div>
                    </div>
                  )}
                </div>
                <p className="mt-4 text-[10px] text-slate-400 font-bold leading-relaxed italic uppercase">
                  * Automatic background sending requires a configured gateway. Manual mode opens a loop for manual clicking.
                </p>
              </div>

              <button type="submit" disabled={loading} className="w-full flex items-center justify-center gap-3 bg-slate-900 hover:bg-black text-white font-black py-6 rounded-[1.8rem] shadow-2xl transition-all disabled:opacity-50">
                {loading ? <Loader2 className="animate-spin" size={24} /> : <Save size={24} />}
                <span>Save All Configurations</span>
              </button>
            </form>
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-white rounded-[3rem] border border-slate-100 p-10 shadow-sm">
            <div className="flex items-center gap-3 mb-8">
              <div className="w-12 h-12 rounded-[1.5rem] bg-emerald-50 text-emerald-600 flex items-center justify-center">
                <Database size={24} />
              </div>
              <h3 className="text-xl font-black text-slate-900 tracking-tight">Device Migration</h3>
            </div>
            <div className="space-y-4">
              <button onClick={handleBackup} disabled={backingUp} className="w-full flex items-center justify-center gap-3 bg-emerald-50 hover:bg-emerald-100 text-emerald-700 font-black py-5 rounded-[1.5rem] transition-all border border-emerald-200">
                {backingUp ? <Loader2 className="animate-spin" size={20} /> : <RefreshCw size={20} />}
                <span>Export JSON Backup</span>
              </button>
              <button onClick={() => fileInputRef.current?.click()} disabled={importing} className="w-full flex items-center justify-center gap-3 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-black py-5 rounded-[1.5rem] transition-all border border-indigo-200">
                {importing ? <Loader2 className="animate-spin" size={20} /> : <DownloadCloud size={20} />}
                <span>Import from Device</span>
              </button>
              <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileImport} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import App from './App';
import Login from './pages/Login';

// --- MOCK API FALLBACK (Local Storage) ---
if (typeof (window as any).api === 'undefined') {
  console.warn("Electron API not found. Falling back to Local Storage mode.");

  (window as any).api = {
    register: async (data: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      if (users.find((u: any) => u.email === data.email)) return { error: 'Email already exists' };
      const newUser = { ...data, id: Math.random().toString(36).substr(2, 9) };
      users.push(newUser);
      localStorage.setItem('cms_users', JSON.stringify(users));
      return { user: newUser };
    },
    login: async (credentials: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      const user = users.find((u: any) => u.email === credentials.email && u.password === credentials.password);
      if (!user) return { error: 'Invalid credentials or user not found' };
      return { user };
    },
    getStats: async () => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const income = finances.filter((f: any) => f.type !== 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      const expenses = finances.filter((f: any) => f.type === 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      return { members: members.length, visitors: JSON.parse(localStorage.getItem('cms_pastoral') || '[]').length, totalIncome: income, totalExpenses: expenses };
    },
    getMembers: async (query: string) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      return members.filter((m: any) => m.fullName.toLowerCase().includes(query.toLowerCase()));
    },
    addMember: async (data: any) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const newMember = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      members.push(newMember);
      localStorage.setItem('cms_members', JSON.stringify(members));
      return newMember;
    },
    getFinances: async () => JSON.parse(localStorage.getItem('cms_finances') || '[]'),
    addFinance: async (data: any) => {
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const newFinance = { ...data, id: Math.random().toString(36).substr(2, 9), date: new Date() };
      finances.push(newFinance);
      localStorage.setItem('cms_finances', JSON.stringify(finances));
      return newFinance;
    },
    getEvents: async () => JSON.parse(localStorage.getItem('cms_events') || '[]'),
    addEvent: async (data: any) => {
      const events = JSON.parse(localStorage.getItem('cms_events') || '[]');
      const newEvent = { ...data, id: Math.random().toString(36).substr(2, 9) };
      events.push(newEvent);
      localStorage.setItem('cms_events', JSON.stringify(events));
      return newEvent;
    },
    getBaptisms: async () => JSON.parse(localStorage.getItem('cms_baptisms') || '[]'),
    addBaptism: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_baptisms') || '[]');
      const settings = JSON.parse(localStorage.getItem('cms_settings') || '{}');

      const prefix = (settings.churchName || 'CHURCH').substring(0, 3).toUpperCase();
      const year = new Date().getFullYear();
      const seq = (logs.length + 1).toString().padStart(4, '0');
      const generatedId = `${prefix}-${year}-${seq}`;

      const newLog = { ...data, memberId: generatedId, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      logs.push(newLog);
      localStorage.setItem('cms_baptisms', JSON.stringify(logs));

      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const memberIndex = members.findIndex((m: any) => m.fullName.toLowerCase() === data.fullName.toLowerCase());
      if (memberIndex > -1) {
        members[memberIndex].memberId = generatedId;
        localStorage.setItem('cms_members', JSON.stringify(members));
      }

      return newLog;
    },
