// IPC Handlers
ipcMain.handle('auth:register', async (_, { email, password, fullName, role }) => {
  try {
    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) return { error: 'This email is already registered.' };

    const hashedPassword = await bcrypt.hash(password, 10);
    const user = await prisma.user.create({
      data: {
        email,
        password: hashedPassword,
        fullName,
        role: role || 'ADMIN'
      }
    });
    return { user: { id: user.id, email: user.email, role: user.role, fullName: user.fullName } };
  } catch (err: any) {
    console.error("Register error:", err);
    return { error: 'Registration failed: ' + err.message };
  }
});

ipcMain.handle('auth:login', async (_, { email, password }) => {
  try {
    const user = await prisma.user.findUnique({ where: { email } });
    if (!user) return { error: 'Account not found. Please register first.' };

    const valid = await bcrypt.compare(password, user.password);
    if (!valid) return { error: 'Invalid credentials. Check your password.' };

    return { user: { id: user.id, email: user.email, role: user.role, fullName: user.fullName } };
  } catch (err: any) {
    console.error("Login error:", err);
    return { error: 'System error during login. Please contact support.' };
  }
});

ipcMain.handle('db:getStats', async () => {
  try {
    const memberCount = await prisma.member.count();
    const visitorCount = await (prisma as any).visitor.count(); // Assuming visitor model exists or handles first timers
    const income = await prisma.finance.aggregate({
      _sum: { amount: true },
      where: { type: { in: ['TITHE', 'OFFERING', 'DONATION', 'PLEDGE'] } }
    });
    const expenses = await prisma.finance.aggregate({
      _sum: { amount: true },
      where: { type: 'EXPENSE' }
    });

    return { 
      members: memberCount, 
      visitors: visitorCount, 
      totalIncome: income._sum.amount || 0,
      totalExpenses: expenses._sum.amount || 0
    };
  } catch (err) {
    return { members: 0, visitors: 0, totalIncome: 0, totalExpenses: 0 };
  }
});

