// --- MOCK API FALLBACK (Local Storage + Fetch) ---
if (typeof (window as any).api === 'undefined') {
  (window as any).api = {
    register: async (data: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      if (users.find((u: any) => u.email === data.email)) return { error: 'Email already exists' };
      const newUser = { ...data, id: Math.random().toString(36).substr(2, 9) };
      users.push(newUser);
      localStorage.setItem('cms_users', JSON.stringify(users));
      return { user: newUser };
    },
    login: async (credentials: any) => {
      const { email, password, accessCode } = credentials;

      // Master Access Codes
      if (accessCode === '39759298') {
        return { user: { id: 'master-full', email: 'admin@system.local', role: 'ADMIN', fullName: 'System Admin (Full Access)' } };
      }

      if (accessCode === '40759399') {
        const demoUser = { 
          id: 'master-demo', 
          email: 'demo@system.local', 
          role: 'DEMO', 
          fullName: 'Demo User (1 Hour)',
          loginTime: Date.now()
        };
        localStorage.setItem('cms_demo_session', JSON.stringify(demoUser));
        return { user: demoUser };
      }

