import React, { useState } from 'react';
import { KeyRound, Mail, Loader2, User, ShieldCheck, ArrowRight, Church, Hash } from 'lucide-react';

interface LoginProps {
  onLogin: (user: any) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [useCode, setUseCode] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [accessCode, setAccessCode] = useState('');
  const [fullName, setFullName] = useState('');
  const [role, setRole] = useState('ADMIN');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const api = (window as any).api;
      const res = await api.login({ email, password, accessCode: useCode ? accessCode : '' });

      if (res.user) {
        onLogin(res.user);
      } else {
        setError(res.error || 'Login failed.');
      }
    } catch (err: any) {
      setError('System Error: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const api = (window as any).api;
      const res = await api.register({ email, password, fullName, role });
      if (res.user) {
        setIsRegister(false);
      } else {
        setError(res.error || 'Registration failed.');
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
        <div className="absolute top-[-10%] left-[-5%] w-[40%] h-[40%] bg-indigo-600 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-[-10%] right-[-5%] w-[30%] h-[30%] bg-blue-600 rounded-full blur-[100px]"></div>
      </div>

      <div className="max-w-[400px] w-full z-10 animate-in fade-in zoom-in duration-300">
        <div className="bg-white rounded-[2.5rem] shadow-2xl p-8 border border-slate-100">
          <div className="text-center mb-6">
            <div className="inline-flex items-center justify-center w-14 h-14 bg-indigo-600 rounded-2xl text-white shadow-xl mb-4">
              <Church size={28} />
            </div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">
              {isRegister ? 'Setup Admin' : 'Church Manager'}
            </h1>
            <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-1">
              {isRegister ? 'New System Installation' : 'Secure Management Portal'}
            </p>
          </div>

          <form onSubmit={isRegister ? handleRegister : handleSubmit} className="space-y-4">
            {error && (
              <div className="bg-red-50 text-red-700 px-4 py-3 rounded-xl text-[10px] font-black border-l-4 border-red-500">
                {error}
              </div>
            )}

            {isRegister && (
              <div className="space-y-4">
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                  <input
                    type="text" required
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-xl py-3 pl-10 pr-4 text-sm font-bold focus:border-indigo-600 outline-none"
                    placeholder="Full Name"
                  />
                </div>
                <div className="relative">
                  <ShieldCheck className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                  <select
                    value={role}
                    onChange={(e) => setRole(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-xl py-3 pl-10 pr-4 text-sm font-bold focus:border-indigo-600 outline-none appearance-none"
                  >
                    <option value="ADMIN">Administrator</option>
                    <option value="PASTOR">Pastor</option>
                  </select>
                </div>
              </div>
            )}

            {!isRegister && (
              <div className="flex bg-slate-100 p-1 rounded-xl mb-2">
                <button 
                  type="button"
                  onClick={() => setUseCode(false)}
                  className={`flex-1 py-1.5 text-[10px] font-black rounded-lg transition-all ${!useCode ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
                >
                  EMAIL
                </button>
                <button 
                  type="button"
                  onClick={() => setUseCode(true)}
                  className={`flex-1 py-1.5 text-[10px] font-black rounded-lg transition-all ${useCode ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
                >
                  ACCESS CODE
                </button>
              </div>
            )}

            {!useCode || isRegister ? (
              <div className="space-y-4">
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                  <input
                    type="email" required
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-xl py-3 pl-10 pr-4 text-sm font-bold focus:border-indigo-600 outline-none"
                    placeholder="Email Address"
                  />
                </div>
                <div className="relative">
                  <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                  <input
                    type="password" required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-xl py-3 pl-10 pr-4 text-sm font-bold focus:border-indigo-600 outline-none"
                    placeholder="Password"
                  />
                </div>
              </div>
            ) : (
              <div className="relative">
                <Hash className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                <input
                  type="password" required
                  value={accessCode}
                  onChange={(e) => setAccessCode(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-100 rounded-xl py-3 pl-10 pr-4 text-sm font-bold focus:border-indigo-600 outline-none"
                  placeholder="Enter Access Code"
                />
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-slate-900 hover:bg-black text-white font-black py-3.5 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 active:scale-95 text-sm"
            >
              {loading ? <Loader2 className="animate-spin" size={18} /> : (
                <>
                  <span>{isRegister ? 'Setup Admin' : 'Login'}</span>
                  <ArrowRight size={16} />
                </>
              )}
            </button>
          </form>

          <div className="mt-8 text-center border-t border-slate-50 pt-6">
            <button 
              onClick={() => {
                setIsRegister(!isRegister);
                setError('');
                setUseCode(false);
              }}
              className="text-[11px] font-black text-indigo-600 hover:underline"
            >
              {isRegister ? 'Already have an account? Login' : 'Create new admin account'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

