            <p className="text-slate-400 font-bold text-[9px] uppercase tracking-widest mt-1">
              {isRegister ? 'Authorized Installation' : 'Secure Management Portal'}
            </p>
          </div>

          <form onSubmit={isRegister ? handleRegister : handleSubmit} className="space-y-3">
            {error && (
              <div className="bg-red-50 text-red-700 px-3 py-2 rounded-lg text-[9px] font-black border-l-4 border-red-500">
                {error}
              </div>
            )}

            {isRegister && (
              <div className="space-y-3">
                <div className="relative">
                  <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                  <input
                    type="text" required
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-lg py-2.5 pl-9 pr-3 text-xs font-bold focus:border-indigo-600 outline-none"
                    placeholder="Full Name"
                  />
                </div>
                <div className="relative">
                  <ShieldCheck className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                  <select
                    value={role}
                    onChange={(e) => setRole(e.target.value)}
