                  >
                    <option value="ADMIN">Administrator</option>
                    <option value="PASTOR">Pastor</option>
                  </select>
                </div>
              </div>
            )}

            {!isRegister && (
              <div className="flex bg-slate-100 p-1 rounded-lg mb-1">
                <button 
