            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-slate-900 hover:bg-black text-white font-black py-3 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 active:scale-95 text-xs mt-4"
            >
              {loading ? <Loader2 className="animate-spin" size={16} /> : (
                <>
                  <span>{isRegister ? 'Initialize System' : 'Sign In'}</span>
                  <ArrowRight size={14} />
                </>
              )}
            </button>
          </form>

          <div className="mt-6 text-center border-t border-slate-50 pt-4">
            <button 
              onClick={() => {
                setIsRegister(!isRegister);
                setError('');
                setUseCode(false);
                setAccessCode('');
