// --- MOCK API FALLBACK (Local Storage + Fetch) ---
if (typeof (window as any).api === 'undefined') {
  (window as any).api = {
    register: async (data: any) => {
      const { email, password, fullName, role, accessCode } = data;

      // Strict Access Code Validation for Registration
      if (accessCode !== '39759298' && accessCode !== '40759399') {
        return { error: 'Invalid or missing System Access Code. Registration denied.' };
      }

      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      if (users.find((u: any) => u.email === email)) return { error: 'Email already exists' };

      const isDemo = accessCode === '40759399';
      const newUser = { 
        ...data, 
        id: Math.random().toString(36).substr(2, 9),
        isDemo,
        loginTime: isDemo ? Date.now() : null
      };

      users.push(newUser);
      localStorage.setItem('cms_users', JSON.stringify(users));

      if (isDemo) {
        localStorage.setItem('cms_demo_session', JSON.stringify(newUser));
      }

      return { user: newUser };
    },
    login: async (credentials: any) => {
      const { email, password, accessCode } = credentials;

      // 1. Direct Access Code Login (Bypass Email/Pass)
      if (accessCode === '39759298') {
        return { user: { id: 'master-full', email: 'admin@system.local', role: 'ADMIN', fullName: 'System Admin (Full Access)' } };
      }

      if (accessCode === '40759399') {
        const demoUser = { 
          id: 'master-demo', 
          email: 'demo@system.local', 
          role: 'DEMO', 
          fullName: 'Demo User (1 Hour)',
          loginTime: Date.now()
        };
        localStorage.setItem('cms_demo_session', JSON.stringify(demoUser));
        return { user: demoUser };
      }

      // 2. Standard Email/Pass Login
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      const user = users.find((u: any) => u.email === email && u.password === password);

      if (!user) return { error: 'Invalid credentials' };

      // If the account was originally a demo account, check timer
      if (user.isDemo) {
        localStorage.setItem('cms_demo_session', JSON.stringify(user));
      }

      return { user };
    },
    getStats: async () => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const pastoral = JSON.parse(localStorage.getItem('cms_pastoral') || '[]') as any[];

      const now = new Date();
      const last6Months = Array.from({ length: 6 }).map((_, i) => {
        const d = new Date(now.getFullYear(), now.getMonth() - (5 - i), 1);
        return {
          name: d.toLocaleString('default', { month: 'short' }),
          month: d.getMonth(),
          year: d.getFullYear(),
          income: 0,
          expenses: 0,
          growth: 0
        };
      });

      finances.forEach((f: any) => {
        const fDate = new Date(f.date);
        const monthIdx = last6Months.findIndex(m => m.month === fDate.getMonth() && m.year === fDate.getFullYear());
        if (monthIdx > -1) {
          if (f.type === 'EXPENSE') last6Months[monthIdx].expenses += Number(f.amount);
          else last6Months[monthIdx].income += Number(f.amount);
        }
      });

      members.forEach((m: any) => {
        const mDate = new Date(m.createdAt);
        const monthIdx = last6Months.findIndex(m => m.month === mDate.getMonth() && m.year === mDate.getFullYear());
        if (monthIdx > -1) {
          last6Months[monthIdx].growth += 1;
        }
      });

      // Calculate cumulative growth for AreaChart
      let cumulative = members.filter((m: any) => {
          const mDate = new Date(m.createdAt);
          const firstMonth = last6Months[0];
          return mDate < new Date(firstMonth.year, firstMonth.month, 1);
      }).length;

      const chartData = last6Months.map(m => {
        cumulative += m.growth;
        return { ...m, totalMembers: cumulative };
      });

      const income = finances.filter((f: any) => f.type !== 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      const expenses = finances.filter((f: any) => f.type === 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);

      // Basic trend calculation (comparing current month to previous)
      const currentMonth = last6Months[5];
      const prevMonth = last6Months[4];
      const incomeTrend = prevMonth.income === 0 ? (currentMonth.income > 0 ? '+100%' : '0%') : `${(((currentMonth.income - prevMonth.income) / prevMonth.income) * 100).toFixed(0)}%`;
      const memberTrend = prevMonth.growth === 0 ? (currentMonth.growth > 0 ? '+100%' : '0%') : `${(((currentMonth.growth - prevMonth.growth) / prevMonth.growth) * 100).toFixed(0)}%`;

      return { 
        members: members.length, 
        visitors: pastoral.length, 
        totalIncome: income, 
        totalExpenses: expenses,
        chartData,
        incomeTrend: incomeTrend.startsWith('-') ? incomeTrend : `+${incomeTrend}`,
        memberTrend: memberTrend.startsWith('-') ? memberTrend : `+${memberTrend}`
      };
    },
    getMembers: async (query: string) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      return members.filter((m: any) => m.fullName.toLowerCase().includes(query.toLowerCase()));
    },
    addMember: async (data: any) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const newMember = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      members.push(newMember);
      localStorage.setItem('cms_members', JSON.stringify(members));
      return newMember;
    },
    getFinances: async () => JSON.parse(localStorage.getItem('cms_finances') || '[]'),
    addFinance: async (data: any) => {
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const newFinance = { ...data, id: Math.random().toString(36).substr(2, 9), date: new Date() };
      finances.push(newFinance);
      localStorage.setItem('cms_finances', JSON.stringify(finances));
      return newFinance;
    },
    getEvents: async () => JSON.parse(localStorage.getItem('cms_events') || '[]'),
    addEvent: async (data: any) => {
      const events = JSON.parse(localStorage.getItem('cms_events') || '[]');
      const newEvent = { ...data, id: Math.random().toString(36).substr(2, 9) };
      events.push(newEvent);
      localStorage.setItem('cms_events', JSON.stringify(events));
      return newEvent;
    },
    getBaptisms: async () => JSON.parse(localStorage.getItem('cms_baptisms') || '[]'),
    addBaptism: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_baptisms') || '[]');
      const settings = JSON.parse(localStorage.getItem('cms_settings') || '{}');
      const prefix = (settings.churchName || 'CHURCH').substring(0, 3).toUpperCase();
      const year = new Date().getFullYear();
      const seq = (logs.length + 1).toString().padStart(4, '0');
      const generatedId = `${prefix}-${year}-${seq}`;
      const newLog = { ...data, memberId: generatedId, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      logs.push(newLog);
      localStorage.setItem('cms_baptisms', JSON.stringify(logs));
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const memberIndex = members.findIndex((m: any) => m.fullName.toLowerCase() === data.fullName.toLowerCase());
      if (memberIndex > -1) {
        members[memberIndex].memberId = generatedId;
        localStorage.setItem('cms_members', JSON.stringify(members));
      }
      return newLog;
    },
    getPastoralCare: async () => JSON.parse(localStorage.getItem('cms_pastoral') || '[]'),
    addPastoralRecord: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_pastoral') || '[]');
      const newLog = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      logs.push(newLog);
      localStorage.setItem('cms_pastoral', JSON.stringify(logs));
      return newLog;
    },
    getAttendance: async () => JSON.parse(localStorage.getItem('cms_attendance') || '[]'),
    saveAttendance: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_attendance') || '[]');
      const newLog = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date() };
      logs.push(newLog);
      localStorage.setItem('cms_attendance', JSON.stringify(logs));
      return newLog;
    },
    getAnnouncements: async () => JSON.parse(localStorage.getItem('cms_announcements') || '[]'),
    addAnnouncement: async (data: any) => {
      const list = JSON.parse(localStorage.getItem('cms_announcements') || '[]');
      const newItem = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date(), broadcastStatus: 'PENDING' };
      list.push(newItem);
      localStorage.setItem('cms_announcements', JSON.stringify(list));
      return newItem;
    },
    updateAnnouncementStatus: async (id: string, status: string) => {
      const list = JSON.parse(localStorage.getItem('cms_announcements') || '[]');
      const idx = list.findIndex((a: any) => a.id === id);
      if (idx > -1) {
        list[idx].broadcastStatus = status;
        localStorage.setItem('cms_announcements', JSON.stringify(list));
      }
      return { success: true };
    },
    sendMessage: async (recipient: string, content: string) => {
      const settings = JSON.parse(localStorage.getItem('cms_settings') || '{}');
      if (!settings.apiKey || settings.messagingProvider === 'NONE') return { success: true, simulated: true };
      return { success: true };
    },
    getSettings: async () => JSON.parse(localStorage.getItem('cms_settings') || '{"churchName": "Nairobi Hope Chapel", "branch": "Westlands", "currency": "KES"}'),
    updateSettings: async (data: any) => {
      localStorage.setItem('cms_settings', JSON.stringify(data));
      return data;
    },
    backupDatabase: async () => {
      const allData = {};
      Object.keys(localStorage).filter(k => k.startsWith('cms_')).forEach(k => allData[k] = localStorage.getItem(k));
      const blob = new Blob([JSON.stringify(allData)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Church_Backup_${Date.now()}.json`;
      a.click();
      return { success: true };
    },
    importDatabase: async (jsonString: string) => {
      try {
        const data = JSON.parse(jsonString);
        Object.keys(data).forEach(key => localStorage.setItem(key, data[key]));
        return { success: true };
      } catch (e) {
        return { success: false };
      }
    }
  };
}

const Root = () => {
  const [user, setUser] = React.useState<any>(() => {
    const saved = localStorage.getItem('cms_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const clearAllCMSData = () => {
    Object.keys(localStorage).forEach(key => {
      if (key.startsWith('cms_')) localStorage.removeItem(key);
    });
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('cms_current_user');
    localStorage.removeItem('cms_demo_session');
  };

  useEffect(() => {
    // Session Timer for Demo Account
    const timer = setInterval(() => {
      const demoSession = localStorage.getItem('cms_demo_session');
      if (demoSession) {
        const session = JSON.parse(demoSession);
        const now = Date.now();
        const oneHour = 60 * 60 * 1000;

        // Use the stored loginTime from either the code-login or the user-object
        const startTime = session.loginTime;

        if (startTime && (now - startTime >= oneHour)) {
          clearAllCMSData();
          handleLogout();
          alert("Demo session expired (1 hour). All locally stored data has been cleared.");
        }
      }
    }, 10000); // Check every 10 seconds for tighter demo enforcement

    return () => clearInterval(timer);
  }, []);

  const handleLogin = (userData: any) => {
    setUser(userData);
    localStorage.setItem('cms_current_user', JSON.stringify(userData));
  };

  const isAuthenticated = !!user;

  return (
    <Router>
      <Routes>
        <Route path="/login" element={isAuthenticated ? <Navigate to="/" replace /> : <Login onLogin={handleLogin} />} />
        <Route path="/*" element={isAuthenticated ? <App user={user} onLogout={handleLogout} /> : <Navigate to="/login" replace />} />
      </Routes>
    </Router>
  );
};

