// --- MOCK API FALLBACK (Local Storage + Persistent Layer) ---
if (typeof (window as any).api === 'undefined') {
  (window as any).api = {
    // Auth & Access
    register: async (data: any) => {
      const { email, password, fullName, role, accessCode } = data;
      if (accessCode !== '39759298' && accessCode !== '40759399') {
        return { error: 'Invalid or missing System Access Code. Registration denied.' };
      }
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      if (users.find((u: any) => u.email === email)) return { error: 'Email already exists' };
      const isDemo = accessCode === '40759399';
      const newUser = { ...data, id: Math.random().toString(36).substr(2, 9), isDemo, loginTime: isDemo ? Date.now() : null };
      users.push(newUser);
      localStorage.setItem('cms_users', JSON.stringify(users));
      if (isDemo) localStorage.setItem('cms_demo_session', JSON.stringify(newUser));
      return { user: newUser };
    },
    login: async (credentials: any) => {
      const { email, password, accessCode } = credentials;
      if (accessCode === '39759298') return { user: { id: 'master-full', email: 'admin@system.local', role: 'ADMIN', fullName: 'System Admin' } };
      if (accessCode === '40759399') {
        const demoUser = { id: 'master-demo', email: 'demo@system.local', role: 'DEMO', fullName: 'Demo User (1 Hour)', loginTime: Date.now() };
        localStorage.setItem('cms_demo_session', JSON.stringify(demoUser));
        return { user: demoUser };
      }
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      const user = users.find((u: any) => u.email === email && u.password === password);
      if (!user) return { error: 'Invalid credentials' };
      if (user.isDemo) localStorage.setItem('cms_demo_session', JSON.stringify(user));
      return { user };
    },

    // Dashboard Stats
    getStats: async () => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const pastoral = JSON.parse(localStorage.getItem('cms_pastoral') || '[]');
      const now = new Date();
      const last6Months = Array.from({ length: 6 }).map((_, i) => {
        const d = new Date(now.getFullYear(), now.getMonth() - (5 - i), 1);
        return { name: d.toLocaleString('default', { month: 'short' }), month: d.getMonth(), year: d.getFullYear(), income: 0, expenses: 0, totalMembers: 0 };
      });
      finances.forEach((f: any) => {
        const fDate = new Date(f.date);
        const monthIdx = last6Months.findIndex(m => m.month === fDate.getMonth() && m.year === fDate.getFullYear());
        if (monthIdx > -1) {
          if (f.type === 'EXPENSE') last6Months[monthIdx].expenses += Number(f.amount);
          else last6Months[monthIdx].income += Number(f.amount);
        }
      });
      let cumulative = 0;
      const chartData = last6Months.map(m => {
        const count = members.filter((mem: any) => {
          const d = new Date(mem.createdAt);
          return d.getMonth() === m.month && d.getFullYear() === m.year;
        }).length;
        cumulative += count;
        return { ...m, totalMembers: cumulative };
      });
      const income = finances.filter((f: any) => f.type !== 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      const expenses = finances.filter((f: any) => f.type === 'EXPENSE').reduce((sum: number, f: any) => sum + Number(f.amount), 0);
      return { members: members.length, visitors: pastoral.length, totalIncome: income, totalExpenses: expenses, chartData, incomeTrend: '+12%', memberTrend: '+5%' };
    },

    // Core Modules
    getMembers: async (query: string) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      return members.filter((m: any) => m.fullName.toLowerCase().includes(query.toLowerCase()));
    },
    addMember: async (data: any) => {
      const members = JSON.parse(localStorage.getItem('cms_members') || '[]');
      const newMember = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() };
      members.push(newMember);
      localStorage.setItem('cms_members', JSON.stringify(members));
      return newMember;
    },
    getFinances: async () => JSON.parse(localStorage.getItem('cms_finances') || '[]'),
    addFinance: async (data: any) => {
      const finances = JSON.parse(localStorage.getItem('cms_finances') || '[]');
      const newFinance = { ...data, id: Math.random().toString(36).substr(2, 9), date: new Date().toISOString() };
      finances.push(newFinance);
      localStorage.setItem('cms_finances', JSON.stringify(finances));
      return newFinance;
    },
    getInventory: async () => JSON.parse(localStorage.getItem('cms_inventory') || '[]'),
    addInventory: async (data: any) => {
      const items = JSON.parse(localStorage.getItem('cms_inventory') || '[]');
      const newItem = { ...data, id: Math.random().toString(36).substr(2, 9), lastService: new Date().toISOString() };
      items.push(newItem);
      localStorage.setItem('cms_inventory', JSON.stringify(items));
      return newItem;
    },
    getCounseling: async () => JSON.parse(localStorage.getItem('cms_counseling') || '[]'),
    addCounseling: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_counseling') || '[]');
      const newLog = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() };
      logs.push(newLog);
      localStorage.setItem('cms_counseling', JSON.stringify(logs));
      return newLog;
    },
    getLibrary: async () => JSON.parse(localStorage.getItem('cms_library') || '[]'),
    addLibraryItem: async (data: any) => {
      const items = JSON.parse(localStorage.getItem('cms_library') || '[]');
      const newItem = { ...data, id: Math.random().toString(36).substr(2, 9), addedAt: new Date().toISOString() };
      items.push(newItem);
      localStorage.setItem('cms_library', JSON.stringify(items));
      return newItem;
    },
    getBaptisms: async () => JSON.parse(localStorage.getItem('cms_baptisms') || '[]'),
    addBaptism: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_baptisms') || '[]');
      const newLog = { ...data, id: Math.random().toString(36).substr(2, 9), memberId: `MEM-${Date.now().toString().slice(-4)}`, createdAt: new Date().toISOString() };
      logs.push(newLog);
      localStorage.setItem('cms_baptisms', JSON.stringify(logs));
      return newLog;
    },
    getAttendance: async () => JSON.parse(localStorage.getItem('cms_attendance') || '[]'),
    saveAttendance: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_attendance') || '[]');
      const newLog = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() };
      logs.push(newLog);
      localStorage.setItem('cms_attendance', JSON.stringify(logs));
      return newLog;
    },
    getPastoralCare: async () => JSON.parse(localStorage.getItem('cms_pastoral') || '[]'),
    addPastoralRecord: async (data: any) => {
      const logs = JSON.parse(localStorage.getItem('cms_pastoral') || '[]');
      const newLog = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() };
      logs.push(newLog);
      localStorage.setItem('cms_pastoral', JSON.stringify(logs));
      return newLog;
    },
    getAnnouncements: async () => JSON.parse(localStorage.getItem('cms_announcements') || '[]'),
    addAnnouncement: async (data: any) => {
      const list = JSON.parse(localStorage.getItem('cms_announcements') || '[]');
      const newItem = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString(), broadcastStatus: 'PENDING' };
      list.push(newItem);
      localStorage.setItem('cms_announcements', JSON.stringify(list));
      return newItem;
    },
    sendMessage: async (recipient: string, content: string) => { return { success: true, simulated: true }; },
    getSettings: async () => JSON.parse(localStorage.getItem('cms_settings') || '{"churchName": "Nairobi Hope Chapel", "branch": "Westlands", "currency": "KES"}'),
    updateSettings: async (data: any) => {
      localStorage.setItem('cms_settings', JSON.stringify(data));
      return data;
    },
    backupDatabase: async () => {
      const all = {}; Object.keys(localStorage).forEach(k => { if (k.startsWith('cms_')) all[k] = localStorage.getItem(k); });
      const blob = new Blob([JSON.stringify(all)], { type: 'application/json' });
      const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `CMS_Backup_${Date.now()}.json`; a.click();
      return { success: true };
    },
    importDatabase: async (json: string) => {
      try { const data = JSON.parse(json); Object.keys(data).forEach(k => localStorage.setItem(k, data[k])); return { success: true }; }
      catch (e) { return { success: false }; }
    }
  };
}

const Root = () => {
  const [user, setUser] = React.useState<any>(() => {
    const saved = localStorage.getItem('cms_current_user');
    return saved ? JSON.parse(saved) : null;
  });
  const handleLogout = () => { setUser(null); localStorage.removeItem('cms_current_user'); localStorage.removeItem('cms_demo_session'); };
  useEffect(() => {
    const timer = setInterval(() => {
      const demo = localStorage.getItem('cms_demo_session');
      if (demo) {
        const s = JSON.parse(demo);
        if (Date.now() - s.loginTime >= 3600000) {
          Object.keys(localStorage).forEach(k => { if (k.startsWith('cms_')) localStorage.removeItem(k); });
          handleLogout(); alert("Demo Expired. Data Cleared.");
        }
      }
    }, 10000);
    return () => clearInterval(timer);
  }, []);
  const handleLogin = (u: any) => { setUser(u); localStorage.setItem('cms_current_user', JSON.stringify(u)); };
  return (
    <Router>
      <Routes>
        <Route path="/login" element={user ? <Navigate to="/" replace /> : <Login onLogin={handleLogin} />} />
        <Route path="/*" element={user ? <App user={user} onLogout={handleLogout} /> : <Navigate to="/login" replace />} />
      </Routes>
    </Router>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<Root />);

