import React, { useState, useEffect } from 'react';
import { Plus, Waves, X, Loader2, Calendar, CheckCircle, Hash, IdCard, Award } from 'lucide-react';
import { jsPDF } from 'jspdf';

const Baptism: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [churchInfo, setChurchInfo] = useState<any>(null);
  const [formData, setFormData] = useState({ fullName: '', baptismDate: '', officiatedBy: '', location: 'Main Sanctuary', status: 'COMPLETED' });

  useEffect(() => { fetchLogs(); fetchChurchInfo(); }, []);

  const fetchChurchInfo = async () => { const api = (window as any).api; const info = await api.getSettings(); setChurchInfo(info); };
  const fetchLogs = async () => { setLoading(true); const api = (window as any).api; const res = await api.getBaptisms(); setLogs(res); setLoading(false); };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addBaptism(formData);
    setShowModal(false);
    setFormData({ fullName: '', baptismDate: '', officiatedBy: '', location: 'Main Sanctuary', status: 'COMPLETED' });
    fetchLogs();
  };

  const printCertificate = (log: any) => {
    const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
    // Border
    doc.setLineWidth(1.5); doc.setDrawColor(79, 70, 229); doc.rect(5, 5, 287, 200);
    doc.setLineWidth(0.5); doc.rect(8, 8, 281, 194);

    // Header
    doc.setTextColor(30, 41, 59); doc.setFontSize(32); doc.setFont('times', 'bold');
    doc.text(churchInfo?.churchName || 'Nairobi Hope Chapel', 148.5, 40, { align: 'center' });

    doc.setFontSize(48); doc.setTextColor(79, 70, 229); doc.text('CERTIFICATE OF BAPTISM', 148.5, 75, { align: 'center' });

    doc.setFontSize(14); doc.setTextColor(100, 116, 139); doc.setFont('helvetica', 'italic');
    doc.text('This is to certify that', 148.5, 95, { align: 'center' });

    doc.setFontSize(34); doc.setTextColor(15, 23, 42); doc.setFont('times', 'bold');
    doc.text(log.fullName.toUpperCase(), 148.5, 115, { align: 'center' });

    doc.setFontSize(14); doc.setTextColor(100, 116, 139); doc.setFont('helvetica', 'normal');
    doc.text(`Having publicly confessed faith in Jesus Christ, was baptized`, 148.5, 130, { align: 'center' });
    doc.text(`on the ${new Date(log.baptismDate).toLocaleDateString()} at ${log.location}`, 148.5, 140, { align: 'center' });

    // Footer Signatures
    doc.setDrawColor(203, 213, 225); doc.line(40, 175, 110, 175); doc.line(187, 175, 257, 175);
    doc.setFontSize(10); doc.text('OFFICIATING PASTOR', 75, 182, { align: 'center' });
    doc.text('CHURCH SECRETARY', 222, 182, { align: 'center' });
    doc.setFont('times', 'bold'); doc.text(log.officiatedBy, 75, 170, { align: 'center' });

    doc.save(`Baptism_Certificate_${log.fullName}.pdf`);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div><h2 className="text-2xl font-black text-slate-900 tracking-tight">Sacraments Registry</h2><p className="text-slate-500 font-bold text-xs uppercase tracking-widest mt-1">Baptismal records and certificate generation</p></div>
        <button onClick={() => setShowModal(true)} className="bg-slate-900 hover:bg-black text-white font-black py-3 px-6 rounded-2xl shadow-xl transition-all flex items-center gap-2"><Plus size={18} /><span>Register Candidate</span></button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? ( <div className="col-span-full py-20 text-center text-slate-400"><Loader2 className="animate-spin inline mr-2" /> Processing Sacraments...</div> ) : logs.length === 0 ? (
          <div className="col-span-full bg-white p-20 rounded-[2.5rem] border border-slate-100 text-center"><Waves size={48} className="text-slate-200 mx-auto mb-4" /><p className="font-black text-slate-400">Registry Empty</p></div>
        ) : logs.map((log) => (
          <div key={log.id} className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm group">
            <div className="flex justify-between items-start mb-6">
              <div className="w-12 h-12 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center"><Waves size={24} /></div>
              <button onClick={() => printCertificate(log)} className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg hover:scale-105 transition-all flex items-center gap-2 font-black text-[10px]"><Award size={16} /><span>CERTIFICATE</span></button>
            </div>
            <h3 className="text-lg font-black text-slate-900 mb-1">{log.fullName}</h3>
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-6">REG ID: {log.memberId}</p>
            <div className="space-y-3 pt-4 border-t border-slate-50">
              <div className="flex justify-between text-[10px] font-bold uppercase text-slate-400 tracking-widest"><span>Date</span><span className="text-slate-900">{new Date(log.baptismDate).toLocaleDateString()}</span></div>
              <div className="flex justify-between text-[10px] font-bold uppercase text-slate-400 tracking-widest"><span>Officiator</span><span className="text-slate-900">{log.officiatedBy}</span></div>
            </div>
          </div>
        ))}
      </div>
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl shadow-2xl animate-in zoom-in duration-200">
            <div className="p-8 border-b border-slate-100 flex items-center justify-between"><h3 className="text-xl font-black text-slate-900">New Baptism Entry</h3><button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><X size={24} className="text-slate-400" /></button></div>
            <form onSubmit={handleAdd} className="p-8 space-y-5">
              <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Candidate Name</label><input required value={formData.fullName} onChange={(e) => setFormData({...formData, fullName: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold" /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Baptism Date</label><input required type="date" value={formData.baptismDate} onChange={(e) => setFormData({...formData, baptismDate: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold" /></div>
                <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Officiated By</label><input required value={formData.officiatedBy} onChange={(e) => setFormData({...formData, officiatedBy: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-indigo-600 outline-none font-bold" /></div>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl hover:bg-black transition-all">Generate Record</button>
            </form>
          </div>
