import { 
  Users, 
  HandHeart, 
  TrendingUp, 
  TrendingDown,
  ArrowUpRight,
  ArrowDownRight,
  Loader2
} from 'lucide-react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  AreaChart,
  Area
} from 'recharts';

const Dashboard: React.FC = () => {
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      setLoading(true);
      try {
        const res = await (window as any).api.getStats();
        setStats(res);
      } catch (e) {
        console.error("Failed to fetch dashboard stats", e);
      } finally {
        setLoading(false);
      }
    };
    fetchStats();
  }, []);

  if (loading) {
    return (
      <div className="h-full flex items-center justify-center bg-blue-100">
        <div className="text-center">
          <Loader2 className="animate-spin text-blue-600 mx-auto mb-4" size={48} />
          <p className="font-black text-blue-400 uppercase tracking-widest text-[10px]">Processing Blue-Engine Data...</p>
        </div>
      </div>
    );
  }

  const cards = [
    { label: 'Registered Members', value: stats.members, icon: Users, color: 'bg-blue-600', trend: stats.memberTrend },
    { label: 'Care Records', value: stats.visitors, icon: HandHeart, color: 'bg-cyan-600', trend: '+2%' },
    { label: 'Total Income', value: `KES ${stats.totalIncome.toLocaleString()}`, icon: TrendingUp, color: 'bg-blue-800', trend: stats.incomeTrend },
    { label: 'Total Expenses', value: `KES ${stats.totalExpenses.toLocaleString()}`, icon: TrendingDown, color: 'bg-indigo-600', trend: '-1%' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {cards.map((card, idx) => {
          const Icon = card.icon;
          const isPositive = card.trend.startsWith('+');
          return (
            <div key={idx} className="bg-blue-50 p-6 rounded-[2.5rem] border border-blue-200 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all">
              <div className="flex items-center justify-between mb-4">
                <div className={`${card.color} w-12 h-12 rounded-2xl text-white flex items-center justify-center shadow-lg`}>
                  <Icon size={24} />
                </div>
                <div className={`flex items-center text-[10px] font-black px-3 py-1.5 rounded-full ${isPositive ? 'bg-blue-100 text-blue-700' : 'bg-red-50 text-red-600'}`}>
                  {isPositive ? <ArrowUpRight size={14} /> : <ArrowDownRight size={14} />}
                  {card.trend}
                </div>
              </div>
              <p className="text-blue-400 text-[10px] font-black uppercase tracking-widest">{card.label}</p>
              <h3 className="text-2xl font-black text-blue-900 mt-1 tracking-tight">{card.value}</h3>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-blue-50 p-8 rounded-[3rem] border border-blue-200 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-lg font-black text-blue-900 tracking-tight">Real Income vs Expenses (KES)</h3>
            <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Last 6 Months</span>
          </div>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#dbeafe" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 10, fontWeight: 900}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 10, fontWeight: 900}} />
                <Tooltip 
                  cursor={{fill: '#eff6ff'}}
                  contentStyle={{ backgroundColor: '#f0f9ff', borderRadius: '24px', border: '1px solid #bfdbfe', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.1)', fontWeight: 'bold', color: '#1e3a8a' }}
                />
                <Bar dataKey="income" fill="#2563eb" radius={[10, 10, 0, 0]} name="Income" />
                <Bar dataKey="expenses" fill="#93c5fd" radius={[10, 10, 0, 0]} name="Expenses" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-blue-50 p-8 rounded-[3rem] border border-blue-200 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-lg font-black text-blue-900 tracking-tight">Congregation Growth History</h3>
            <div className={`flex items-center gap-2 text-xs font-black ${stats.memberTrend.startsWith('+') ? 'text-blue-700' : 'text-red-600'}`}>
              <TrendingUp size={16} />
              <span>{stats.memberTrend}</span>
            </div>
          </div>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats.chartData}>
                <defs>
                  <linearGradient id="colorGrowth" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#dbeafe" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 10, fontWeight: 900}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 10, fontWeight: 900}} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#f0f9ff', borderRadius: '24px', border: '1px solid #bfdbfe', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.1)', fontWeight: 'bold', color: '#1e3a8a' }}
                />
                <Area type="monotone" dataKey="totalMembers" stroke="#2563eb" strokeWidth={4} fillOpacity={1} fill="url(#colorGrowth)" name="Members" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Search, Plus, User, Mail, Phone, MapPin, Briefcase, X, Download, Loader2, MessageCircle, Hash } from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

const Members: React.FC = () => {
  const [members, setMembers] = useState<any[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: '',
    gender: 'MALE',
    dob: '',
    address: '',
    ministry: '',
    branch: 'Main Branch',
    status: 'ACTIVE'
  });

  useEffect(() => {
    fetchMembers();
  }, [search]);

  const fetchMembers = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getMembers(search);
    setMembers(res);
    setLoading(false);
  };

  const handleAddMember = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addMember(formData);
    setShowModal(false);
    setFormData({
      fullName: '', email: '', phone: '', gender: 'MALE', 
      dob: '', address: '', ministry: '', branch: 'Main Branch', status: 'ACTIVE'
    });
    fetchMembers();
  };

  const openWhatsApp = (m: any) => {
    const url = `https://wa.me/${m.phone.replace(/\D/g, '')}?text=${encodeURIComponent(`Greetings ${m.fullName}, we hope you're having a blessed day!`)}`;
    window.open(url, '_blank');
  };

  const exportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(20);
    doc.text('Church Member Directory', 14, 22);
    const tableData = members.map(m => [m.memberId || 'PENDING', m.fullName, m.email, m.phone, m.ministry || 'N/A', m.status]);
    (doc as any).autoTable({
      startY: 35,
      head: [['ID', 'Full Name', 'Email', 'Phone', 'Ministry', 'Status']],
      body: tableData,
      headStyles: { fillColor: [37, 99, 235] },
      theme: 'grid'
    });
    doc.save('church_members_kes.pdf');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-blue-900 tracking-tight">Congregation Directory</h2>
          <p className="text-blue-500 font-bold text-xs uppercase tracking-widest mt-1">Manage all church members and leaders</p>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={exportPDF} className="flex items-center gap-2 bg-blue-50 border border-blue-200 hover:bg-blue-200 text-blue-700 font-bold py-3 px-6 rounded-2xl transition-all shadow-sm">
            <Download size={18} />
            <span>Export PDF</span>
          </button>
          <button onClick={() => setShowModal(true)} className="flex items-center gap-2 bg-blue-700 hover:bg-blue-800 text-white font-black py-3 px-6 rounded-2xl shadow-xl transition-all">
            <Plus size={18} />
            <span>Add Member</span>
          </button>
        </div>
      </div>

      <div className="bg-blue-50 p-4 rounded-[2rem] border border-blue-200 shadow-sm">
        <div className="relative">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-blue-400" size={18} />
          <input 
            type="text" 
            placeholder="Search by name, contact or location..."
            className="w-full pl-14 pr-4 py-4 bg-blue-100 border-2 border-blue-100 rounded-2xl focus:border-blue-600 outline-none transition-all font-bold text-blue-900 placeholder:text-blue-300"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-blue-50 rounded-[2.5rem] border border-blue-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-blue-100/50 text-[10px] font-black text-blue-500 uppercase tracking-[0.2em] border-b border-blue-200">
                <th className="px-8 py-5">Member</th>
                <th className="px-8 py-5">Contact Info</th>
                <th className="px-8 py-5 text-center">ID / Dept</th>
                <th className="px-8 py-5 text-center">Status</th>
                <th className="px-8 py-5 text-right">Reach Out</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-blue-100">
              {loading ? (
                <tr><td colSpan={5} className="p-12 text-center text-blue-400 font-bold"><Loader2 className="animate-spin inline mr-2" /> Syncing Blue Directory...</td></tr>
              ) : members.length === 0 ? (
                <tr><td colSpan={5} className="p-16 text-center text-blue-400 font-bold italic">No members found matching your search.</td></tr>
              ) : members.map((m) => (
                <tr key={m.id} className="hover:bg-blue-100/50 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-blue-200 flex items-center justify-center text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-all font-black">
                        {m.fullName.charAt(0)}
                      </div>
                      <div>
                        <p className="font-black text-blue-900 leading-none">{m.fullName}</p>
                        <p className="text-[10px] text-blue-500 font-bold uppercase mt-1 tracking-wider">{m.branch}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2 text-blue-700 text-xs font-bold">
                        <Mail size={14} className="text-blue-300" /> <span>{m.email}</span>
                      </div>
                      <div className="flex items-center gap-2 text-blue-700 text-xs font-bold">
                        <Phone size={14} className="text-blue-300" /> <span>{m.phone}</span>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <div className="flex flex-col items-center">
                      <div className="flex items-center gap-1 text-[9px] font-black text-blue-600 uppercase mb-1">
                        <Hash size={10} />
                        <span>{m.memberId || 'N/A'}</span>
                      </div>
                      <span className="text-xs font-black text-blue-800 bg-blue-200 px-3 py-1 rounded-lg">
                        {m.ministry || 'General'}
                      </span>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <span className={`px-3 py-1 rounded-full text-[9px] font-black tracking-widest uppercase ${
                      m.status === 'ACTIVE' ? 'bg-blue-200 text-blue-700' : 'bg-blue-100 text-blue-400'
                    }`}>
                      {m.status}
                    </span>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <button onClick={() => openWhatsApp(m)} className="p-2.5 text-blue-600 hover:bg-blue-200 rounded-xl transition-all">
                      <MessageCircle size={20} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-blue-950/70 backdrop-blur-sm">
          <div className="bg-blue-50 rounded-[2.5rem] w-full max-w-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 border border-blue-200">
            <div className="p-8 border-b border-blue-100 flex items-center justify-between bg-blue-100/30">
              <h3 className="text-xl font-black text-blue-900">Add Congregation Member</h3>
              <button onClick={() => setShowModal(false)} className="p-2 hover:bg-blue-200 rounded-full transition-colors">
                <X size={24} className="text-blue-400" />
              </button>
            </div>
            <form onSubmit={handleAddMember} className="p-8 grid grid-cols-2 gap-6">
              <div className="col-span-2">
                <label className="block text-[10px] font-black text-blue-500 uppercase tracking-widest mb-2">Full Legal Name</label>
                <input required type="text" value={formData.fullName} onChange={(e) => setFormData({...formData, fullName: e.target.value})} className="w-full px-5 py-4 bg-blue-100 border-2 border-blue-100 rounded-2xl focus:border-blue-600 outline-none font-bold text-blue-900" />
              </div>
              <div>
                <label className="block text-[10px] font-black text-blue-500 uppercase tracking-widest mb-2">Phone</label>
                <input required type="text" value={formData.phone} onChange={(e) => setFormData({...formData, phone: e.target.value})} className="w-full px-5 py-4 bg-blue-100 border-2 border-blue-100 rounded-2xl focus:border-blue-600 outline-none font-bold text-blue-900" />
              </div>
              <div>
                <label className="block text-[10px] font-black text-blue-500 uppercase tracking-widest mb-2">Ministry/Dept</label>
                <select value={formData.ministry} onChange={(e) => setFormData({...formData, ministry: e.target.value})} className="w-full px-5 py-4 bg-blue-100 border-2 border-blue-100 rounded-2xl focus:border-blue-600 outline-none font-bold text-blue-900">
                  <option value="">None / General</option>
                  <option value="CHOIR">Worship Team</option>
                  <option value="MEDIA">Media & IT</option>
                  <option value="USHERS">Protocol / Ushers</option>
                  <option value="CHILDREN">Sunday School</option>
                </select>
              </div>
              <div className="col-span-2 mt-4">
                <button type="submit" className="w-full bg-blue-700 text-white font-black py-5 rounded-2xl shadow-xl hover:bg-blue-800 transition-all">Register Member</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Members;

import React, { useState, useEffect } from 'react';
import { Wallet, Search, Plus, Filter, FileSpreadsheet, X, Loader2, DollarSign, MessageCircle } from 'lucide-react';
import * as XLSX from 'xlsx';

const Finances: React.FC = () => {
  const [finances, setFinances] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    type: 'OFFERING',
    memberId: '',
    memberPhone: ''
  });

  useEffect(() => {
    fetchFinances();
  }, []);

  const fetchFinances = async () => {
    setLoading(true);
    const api = (window as any).api;
    const res = await api.getFinances();
    setFinances(res);
    setLoading(false);
  };

  const handleAddFinance = async (e: React.FormEvent) => {
    e.preventDefault();
    const api = (window as any).api;
    await api.addFinance({
      ...formData,
      amount: parseFloat(formData.amount)
    });
    setShowModal(false);
    setFormData({ description: '', amount: '', type: 'OFFERING', memberId: '', memberPhone: '' });
    fetchFinances();
  };

  const totals = finances.reduce((acc, f) => {
    if (f.type === 'EXPENSE') acc.expenses += f.amount;
    else acc.income += f.amount;
    return acc;
  }, { income: 0, expenses: 0 });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-blue-900 tracking-tight">Treasury Management</h2>
          <p className="text-blue-500 font-bold text-xs uppercase tracking-widest mt-1">Financial stewardship in KES</p>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => XLSX.writeFile(XLSX.utils.book_new(), "fin.xlsx")} className="flex items-center gap-2 bg-blue-50 border border-blue-200 hover:bg-blue-200 text-blue-700 font-bold py-3 px-6 rounded-2xl transition-all shadow-sm">
            <FileSpreadsheet size={18} />
            <span>Export Report</span>
          </button>
          <button onClick={() => setShowModal(true)} className="flex items-center gap-2 bg-blue-700 hover:bg-blue-800 text-white font-black py-3 px-6 rounded-2xl shadow-xl transition-all">
            <Plus size={18} />
            <span>Record Transaction</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-blue-700 p-8 rounded-[2.5rem] border border-blue-600 shadow-xl text-white">
          <p className="text-[10px] font-black text-blue-200 uppercase tracking-[0.2em] mb-1">Net Balance</p>
          <p className="text-3xl font-black">KES {(totals.income - totals.expenses).toLocaleString()}</p>
        </div>
        <div className="bg-blue-50 p-8 rounded-[2.5rem] border border-blue-200 shadow-sm border-l-4 border-l-blue-500">
          <p className="text-[10px] font-black text-blue-500 uppercase tracking-[0.2em] mb-1">Total Revenue</p>
          <p className="text-2xl font-black text-blue-900">KES {totals.income.toLocaleString()}</p>
        </div>
        <div className="bg-blue-50 p-8 rounded-[2.5rem] border border-blue-200 shadow-sm border-l-4 border-l-red-500">
          <p className="text-[10px] font-black text-red-500 uppercase tracking-[0.2em] mb-1">Total Expenses</p>
          <p className="text-2xl font-black text-blue-900">KES {totals.expenses.toLocaleString()}</p>
        </div>
      </div>

      <div className="bg-blue-50 rounded-[2.5rem] border border-blue-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-blue-100/50 text-[10px] font-black text-blue-500 uppercase tracking-[0.2em] border-b border-blue-200">
                <th className="px-8 py-5">Date</th>
                <th className="px-8 py-5">Description</th>
                <th className="px-8 py-5">Type</th>
                <th className="px-8 py-5 text-right">Amount (KES)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-blue-100">
              {loading ? (
                <tr><td colSpan={4} className="p-12 text-center text-blue-400 font-bold"><Loader2 className="animate-spin inline mr-2" /> Syncing Blue Engine...</td></tr>
              ) : finances.length === 0 ? (
                <tr><td colSpan={4} className="p-16 text-center text-blue-400 font-bold italic">No financial transactions recorded.</td></tr>
              ) : finances.map((f) => (
                <tr key={f.id} className="hover:bg-blue-100/50 transition-colors">
                  <td className="px-8 py-5 text-xs font-bold text-blue-600 uppercase">{new Date(f.date).toLocaleDateString()}</td>
                  <td className="px-8 py-5 text-blue-900 font-black">{f.description}</td>
                  <td className="px-8 py-5">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${
                      f.type === 'EXPENSE' ? 'bg-red-50 text-red-600' : 'bg-blue-200 text-blue-800'
                    }`}>
                      {f.type}
                    </span>
                  </td>
                  <td className={`px-8 py-5 text-right font-black text-lg ${f.type === 'EXPENSE' ? 'text-red-600' : 'text-blue-900'}`}>
                    {f.type === 'EXPENSE' ? '-' : ''}{f.amount.toLocaleString()}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};
export default Finances;

import { app, BrowserWindow, ipcMain, dialog } from 'electron';
import * as path from 'path';
import { PrismaClient } from '@prisma/client';
import * as bcrypt from 'bcryptjs';
import * as fs from 'fs';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Initialize Prisma
const prisma = new PrismaClient();

async function checkDbConnection() {
  try {
    await prisma.$connect();
    console.log("Local SQLite Database Online");

    // Ensure default settings exist
    const count = await (prisma as any).settings.count();
    if (count === 0) {
      await (prisma as any).settings.create({
        data: {
          id: "singleton",
          churchName: "Nairobi Hope Chapel",
          branch: "Westlands",
          currency: "KES"
        }
      });
    }
  } catch (e) {
    console.error("Database connection failed. Run 'npx prisma migrate dev'.");
  }
}

function createWindow() {
  const win = new BrowserWindow({
    width: 1366,
    height: 900,
    minWidth: 1100,
    minHeight: 700,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
    },
    title: "Church OS - Professional CMS",
    icon: path.join(__dirname, '../public/icon.ico') // If exists
  });

  // Remove menu bar for clean "app" feel
  win.setMenuBarVisibility(false);

  if (process.env.NODE_ENV === 'development') {
    win.loadURL('http://localhost:5173');
  } else {
    win.loadFile(path.join(__dirname, '../dist/index.html'));
  }
}

app.whenReady().then(async () => {
  await checkDbConnection();
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', async () => {
  await prisma.$disconnect();
  if (process.platform !== 'darwin') app.quit();
});

// --- AUTH HANDLERS ---
ipcMain.handle('auth:register', async (_, { email, password, fullName, role }) => {
  try {
    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) return { error: 'Account already registered.' };
    const hashedPassword = await bcrypt.hash(password, 10);
    const user = await prisma.user.create({
      data: { email, password: hashedPassword, fullName, role: role || 'ADMIN' }
    });
    return { user: { id: user.id, email: user.email, role: user.role, fullName: user.fullName } };
