import React, { useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import App from './App';
import Login from './pages/Login';

// Check if we are in Electron. If so, use the contextBridge.
const isElectron = typeof (window as any).api !== 'undefined';

// --- BROWSER FALLBACK MOCK (Used if running outside Electron) ---
if (!isElectron) {
  console.warn("Running in Browser Mode: Using LocalStorage Mock. DB changes will NOT persist to SQLite file.");
  (window as any).api = {
    register: async (data: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      if (users.find((u: any) => u.email === data.email)) return { error: 'Exists' };
      users.push(data); localStorage.setItem('cms_users', JSON.stringify(users));
      return { user: data };
    },
    login: async (creds: any) => {
      const users = JSON.parse(localStorage.getItem('cms_users') || '[]');
      const user = users.find((u: any) => u.email === creds.email);
      return user ? { user } : { error: 'Not found' };
    },
    getStats: async () => ({ members: 0, visitors: 0, totalIncome: 0, totalExpenses: 0, chartData: [], memberTrend: '+0%', incomeTrend: '+0%' }),
    getMembers: async () => JSON.parse(localStorage.getItem('cms_members') || '[]'),
    addMember: async (data: any) => {
      const list = JSON.parse(localStorage.getItem('cms_members') || '[]');
      list.push(data); localStorage.setItem('cms_members', JSON.stringify(list));
      return data;
    },
    getFinances: async () => [],
    addFinance: async (data: any) => data,
    getEvents: async () => [],
    addEvent: async (data: any) => data,
    getBaptisms: async () => [],
    addBaptism: async (data: any) => data,
    getPastoralCare: async () => [],
    addPastoralRecord: async (data: any) => data,
    getAttendance: async () => [],
    saveAttendance: async (data: any) => data,
    getSettings: async () => ({ churchName: "Church OS Browser", currency: "KES" }),
    updateSettings: async (data: any) => data,
    backupDatabase: async () => ({ success: true }),
    importDatabase: async () => ({ success: true })
  };
}

const Root = () => {
  const [user, setUser] = React.useState<any>(() => {
    const saved = localStorage.getItem('cms_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const handleLogout = () => { 
    setUser(null); 
    localStorage.removeItem('cms_current_user'); 
  };

  const handleLogin = (u: any) => { 
    setUser(u); 
    localStorage.setItem('cms_current_user', JSON.stringify(u)); 
  };

  return (
    <Router>
      <Routes>
        <Route path="/login" element={user ? <Navigate to="/" replace /> : <Login onLogin={handleLogin} />} />
        <Route path="/*" element={user ? <App user={user} onLogout={handleLogout} /> : <Navigate to="/login" replace />} />
      </Routes>
    </Router>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<Root />);

