import { app, BrowserWindow, ipcMain, dialog } from 'electron';
import * as path from 'path';
import { PrismaClient } from '@prisma/client';
import * as bcrypt from 'bcryptjs';
import * as fs from 'fs';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Initialize Prisma
const prisma = new PrismaClient();

async function checkDbConnection() {
  try {
    await prisma.$connect();
    console.log("Local SQLite Database Online");

    // Ensure default settings exist
    const count = await (prisma as any).settings.count();
    if (count === 0) {
      await (prisma as any).settings.create({
        data: {
          id: "singleton",
          churchName: "Nairobi Hope Chapel",
          branch: "Westlands",
          currency: "KES"
        }
      });
    }
  } catch (e) {
    console.error("Database connection failed. Run 'npx prisma migrate dev'.");
  }
}

function createWindow() {
  const win = new BrowserWindow({
    width: 1366,
    height: 900,
    minWidth: 1100,
    minHeight: 700,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
    },
    title: "Church OS - Professional CMS",
    icon: path.join(__dirname, '../public/icon.ico') // If exists
  });

  // Remove menu bar for clean "app" feel
  win.setMenuBarVisibility(false);

  if (process.env.NODE_ENV === 'development') {
    win.loadURL('http://localhost:5173');
  } else {
    win.loadFile(path.join(__dirname, '../dist/index.html'));
  }
}

app.whenReady().then(async () => {
  await checkDbConnection();
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', async () => {
  await prisma.$disconnect();
  // Fixed: Cast 'process' to 'any' to resolve the 'platform' property access error in TypeScript
  if ((process as any).platform !== 'darwin') app.quit();
});

