ipcMain.handle('auth:register', async (_, { email, password, fullName, role }) => {
  try {
    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) return { error: 'Account already registered.' };
    const hashedPassword = await bcrypt.hash(password, 10);
    const user = await prisma.user.create({
      data: { email, password: hashedPassword, fullName, role: role || 'ADMIN' }
    });
    return { user: { id: user.id, email: user.email, role: user.role, fullName: user.fullName } };
  } catch (err: any) {
    return { error: err.message };
  }
});

